import type { ExtraGuides } from '../../i18n/blog';

/** Complete French translations of the 26 remaining base journal articles. */
export const remainingFr: ExtraGuides = {
'designing-for-real-life-play': {
title: 'Concevoir un jeu pour la vraie vie des joueurs', dek: 'Pourquoi se demander si le jeu trouve sa place dans la vie vaut mieux que chercher à augmenter le nombre d’heures jouées.', imageAlt: 'Une courte séance de puzzle sur téléphone, près d’une tasse de thé et d’une fenêtre lumineuse', tags: ['conception de jeux','jeu mobile','pratique de jeu saine','recherche'],
intro: 'Un jeu peut être délicieux et pourtant mal s’inscrire dans une journée. La question de conception la plus utile n’est pas « Comment faire rester les joueurs ? », mais « Cette expérience correspond-elle à la façon dont les gens veulent passer leur temps ? »',
keyTakeaways: ['Les études à grande échelle invitent à ne pas considérer les heures jouées comme une mesure complète du bien-être des joueurs.','L’adéquation tient au moment, aux raisons et à la manière de jouer, pas seulement à l’horloge.','Un jeu qui accepte les pauses doit permettre de s’arrêter, de revenir et de se repérer facilement.'],
sections: {
'hours-are-not-the-whole-story': {title: 'Les heures ne disent pas tout', paragraphs: ['Deux études récentes de l’Oxford Internet Institute font une distinction utile. L’une a suivi le temps de jeu enregistré objectivement chez des dizaines de milliers de joueurs adultes et trouvé peu d’éléments indiquant que ce temps modifiait lui-même le bien-être de façon causale. L’autre a étudié 703 adultes jouant occasionnellement à des jeux Nintendo, sur plus de 140 000 heures, et constaté que la valeur perçue — la place du jeu dans leur vie — était plus informative que le temps brut.','Cela ne signifie pas que l’on puisse ignorer le contexte. Une horloge est simplement un instrument grossier. Selon la personne et le jour, un même nombre de minutes peut représenter un repos bienvenu, un lien social, une fuite ou une obligation indésirable.']},
'fit-is-a-design-material': {title: 'L’adéquation à la vie se travaille dans la conception', paragraphs: ['Pour un puzzle mobile, cette adéquation apparaît dans de petites décisions. Le premier écran s’explique-t-il de lui-même ? Peut-on finir un plateau sans interruption surprise ? Revenir après une semaine est-il accueillant plutôt qu’éprouvant ? La sauvegarde de la progression réduit-elle l’effort de mémoire ?','OutBrick propose un objectif par plateau, une progression qui vous suit entre appareils grâce à iCloud et des widgets d’écran d’accueil qui indiquent où vous en êtes. La conception est volontairement lisible d’un coup d’œil. Elle doit résister au passage d’une minute libre à un après-midi chargé sans vous obliger à reconstruire toute l’expérience.'], bullets: ['Une séance a un point d’arrêt naturel','Le chemin du retour est visible sans pression','La progression reste lisible après une absence','Le jeu n’a pas besoin d’une série quotidienne pour que la journée compte']},
'research-the-quality-of-play': {title: 'Étudier la qualité du jeu', paragraphs: ['Un article de Nature Scientific Data a constitué un jeu de données longitudinales intensives autour de PowerWash Simulator, en associant des mesures répétées du bien-être à des millions d’événements de jeu. Son apport est méthodologique : les chercheurs peuvent apprendre davantage en étudiant ce que font les joueurs et ce qu’ils ressentent au fil du temps, plutôt qu’en se fiant uniquement aux estimations rétrospectives des heures.','Cette approche change aussi ce qu’un studio devrait observer. Un signal sain n’est pas simplement une hausse du nombre de séances. Ce peut être un joueur qui trouve une difficulté confortable, qui revient parce qu’une mécanique a du sens ou qui s’arrête après une conclusion satisfaisante. Les indicateurs doivent aider l’équipe à repérer ces tendances, sans les aplatir dans un classement unique.']},
'a-small-design-promise': {title: 'Une petite promesse de conception', paragraphs: ['La promesse d’OutBrick est simple : proposer un plateau qui mérite réflexion, puis rendre au joueur son temps. Rien n’interrompt un plateau, et aucune vidéo ne démarre sans qu’il ait appuyé sur un bouton pour la demander. La première annulation de chaque plateau est gratuite et ne peut pas être épuisée. Il n’est pas non plus nécessaire de garder l’application ouverte pour que le jeu reste intéressant : les vies reviennent à raison d’une toutes les trente minutes, que vous regardiez ou non.','Nous voulons toujours que les joueurs reviennent. La différence tient à l’origine de l’invitation : un plateau avec une idée claire, neuf amis en briques qui réagissent quand vous le terminez et la satisfaction discrète de voir un chemin invisible trente secondes plus tôt.']}
}, pullQuote: 'Proposer un plateau qui mérite réflexion, puis rendre au joueur son temps.', faqs: [{question: 'OutBrick suit-il mon temps de jeu ?', answer: 'Votre progression reste sur votre appareil et dans votre propre iCloud, et l’application ne contient aucun SDK d’analyse. Le fournisseur de vidéos récompensées recueille les données décrites dans la [politique de confidentialité](/privacy). Cet article traite de méthodes de recherche, et ne fait pas de promesse sur tous les jeux.'},{question: 'Que signifie l’adéquation du jeu à la vie ?', answer: 'C’est le sentiment personnel du joueur que le temps consacré au jeu s’accorde avec le reste de sa vie. Cela diffère d’un simple total d’heures.'}]
},
'angry-birds-success-lessons': {
title: 'Angry Birds : le long chemin vers un succès', dek: 'L’histoire racontée par Rovio rappelle utilement que les jeux emblématiques sont souvent la partie visible d’un bien plus long apprentissage.', imageAlt: 'Des blocs lanceurs rouges abstraits visant une pile ludique de briques-jouets vertes', tags: ['Angry Birds','jeux mobiles','succès d’un jeu','itération'], intro: 'Les récits de succès ressemblent souvent à des coups de foudre. L’histoire d’entreprise de Rovio raconte quelque chose de plus utile : des dizaines d’essais, une occasion claire sur mobile et une équipe qui a continué à créer assez longtemps pour être prête à l’arrivée de la bonne idée.', keyTakeaways: ['Rovio présente Angry Birds comme son 52e jeu, après 51 projets et un épisode proche de la faillite.','La leçon consiste à apprendre de chaque petite expérience, et non à publier jusqu’à ce que la chance arrive.','Un succès peut devenir un univers, mais il faut d’abord réussir l’interaction centrale.'], sections: {
 'the-52nd-game': {title: 'Le 52e jeu compte', paragraphs: ['Selon l’histoire de Rovio, le premier Angry Birds était son 52e jeu. L’entreprise avait déjà développé des dizaines de titres pour les premières plateformes mobiles et décrit une équipe proche de la faillite, ayant besoin d’un grand succès. Angry Birds a été créé en huit mois, puis ses téléchargements ont fortement augmenté en quelques semaines.','C’est une réussite, mais pas une recette. La source est l’histoire publiée par l’entreprise elle-même ; son langage est donc promotionnel et doit être lu avec d’autres éléments. La leçon pratique est plus limitée : la percée visible reposait sur beaucoup d’itérations antérieures qui font rarement les gros titres.']},
 'make-the-core-readable': {title: 'Rendre le cœur du jeu lisible', paragraphs: ['Angry Birds rendait le lancement, la visée et la collision assez lisibles pour être vite compris. L’interaction était ludique, mais offrait un modèle mental clair : tirer, relâcher, regarder la structure réagir. Cette lisibilité aide à comprendre comment une mécanique simple pouvait porter de nombreux niveaux et convenir à beaucoup de joueurs.','OutBrick repose sur le même respect des premières secondes. Faites glisser une brique : elle continue jusqu’à rencontrer un obstacle. Faites sortir toutes les briques par la porte de leur couleur : le plateau est terminé. La règle s’apprend en cinq secondes environ. Ensuite, le jeu doit donner assez d’indices pour vous permettre d’en tirer parti avec ingéniosité.']},
 'a-franchise-is-a-conversation': {title: 'Une franchise est une conversation', paragraphs: ['Le rapport annuel 2019 de Rovio décrit une stratégie allant au-delà du jeu : regarder, consommer et interagir. Il indique aussi que l’exploitation continue et les mises à jour ont aidé certains titres à générer des revenus pendant plusieurs années. Ce sont des faits commerciaux rapportés par une partie intéressée, pas la preuve qu’une tactique garantit une communauté durable.','L’idée de conception reste précieuse : un univers devient plus fort lorsque les points de contact qui l’entourent appartiennent au même monde. Les [neuf amis en briques](/mascots) d’OutBrick, ses widgets, son bonus quotidien de pièces et ses 167 villages en briques ramènent tous au même plateau. Aucun n’est un produit séparé qui rivalise pour votre attention.']},
 'what-we-keep-for-outbrick': {title: 'Ce que nous retenons pour OutBrick', paragraphs: ['Nous retenons de l’histoire d’Angry Birds ce qui est facile à mettre en pratique et difficile à feindre : continuer à travailler son métier, garder la première interaction claire et faire voyager la personnalité du jeu avec le joueur. Nous laissons de côté l’idée que le succès se réduit à un classement de téléchargements.','OutBrick reste un petit jeu. Son ambition prend la forme d’un plateau agréable en main, d’un joueur qui peut revenir sans devoirs et d’un travail qui s’améliore une brique à la fois. Pour un autre chemin vers la même idée, lisez [comment Tetris garde un petit ensemble de règles ouvert](/blog/tetris-simple-rules-infinite-variation).']}
}, pullQuote: 'La percée visible reposait sur beaucoup d’itérations antérieures qui font rarement les gros titres.', faqs: []
},
'monument-valley-less-game-more-experience': {
title: 'Monument Valley : faire moins, mais faire complet', dek: 'Un regard sur l’idée d’ustwo « moins de jeu, plus d’expérience » et sur ce qu’OutBrick lui emprunte.', imageAlt: 'Un escalier pastel impossible assemblé avec des briques-jouets brillantes originales', tags: ['Monument Valley','jeux mobiles','expérience utilisateur','conception de puzzles'], intro: 'Certains jeux gagnent l’attention en ajoutant toujours plus. Monument Valley est devenu une référence en faisant de chaque écran un petit lieu achevé. Son histoire de conception parle moins du minimalisme comme esthétique que du choix de ce qui mérite l’attention du joueur.', keyTakeaways: ['ustwo décrit Monument Valley comme un parcours mobile complet, sans tâches répétitives, pression de l’échec ni dépendance aux classements.','GDC présente sa conception comme une rencontre entre architecture impossible et approche centrée sur l’expérience utilisateur.','OutBrick emprunte le principe d’un moment complet : chaque plateau doit avoir sa forme, son ambiance et sa fin.'], sections: {
'a-screen-can-be-a-place': {title: 'Un écran peut être un lieu', paragraphs: ['La page du projet d’ustwo décrit Monument Valley comme une expérience courte et complète : des mécaniques originales, sans répétition laborieuse, pression de l’échec, étoiles à collectionner ni classements. L’ambition déclarée du studio était que les joueurs terminent tout le jeu sur mobile, du début à la fin.','Ce récit du studio explique une intention plutôt qu’il ne mesure une causalité. Il ne prouve pas qu’un choix particulier a causé le succès du jeu. Il offre toutefois une position claire : un jeu mobile peut être une succession de moments composés avec soin plutôt qu’une demande sans fin de temps supplémentaire.']},
'less-game-more-experience': {title: 'Moins de jeu, plus d’expérience', paragraphs: ['La présentation de la conférence GDC du concepteur principal Ken Wong relie l’architecture impossible de M. C. Escher à l’expérience d’ustwo comme studio d’UX. Chaque écran était traité comme une œuvre, et l’équipe repensait le jeu comme une expérience utilisateur plutôt que comme une seule épreuve de difficulté.','Ce changement est utile aux créateurs de puzzles. La difficulté n’est qu’une dimension de la valeur. Un plateau peut aussi marquer par sa silhouette, une petite surprise ou un instant où l’on découvre la règle sous un angle nouveau. L’interface indigo profond et les villages en briques d’OutBrick donnent un cadre à ces moments, sans aucune horloge pour les presser.']},
'complete-does-not-mean-easy': {title: 'Complet ne signifie pas facile', paragraphs: ['Une expérience complète peut tout de même demander de la concentration. La différence essentielle tient à la compréhension du but de l’épreuve et au respect du joueur une fois celle-ci terminée.','OutBrick permet à un plateau d’être ardu sans rendre toute l’application hostile. La première annulation gratuite sur chaque plateau et une annulation gratuite lorsque le plateau se bloque lient l’arc émotionnel à la résolution plutôt qu’au paiement d’une erreur. Le plateau peut être difficile. La relation n’a pas à l’être.']},
 'the-outbrick-translation': {title: 'La transposition dans OutBrick', paragraphs: ['Pour OutBrick, « moins de jeu » signifie moins de friction entre le joueur et l’idée du plateau. Un écran peut suffire. Un coup peut suffire à enseigner une règle. Un plateau terminé peut suffire à conclure une séance sur une bonne note.','Nous ne cherchons pas à faire une copie réduite du succès d’autrui. Nous voulons un univers où un petit puzzle soit complet à sa façon ; c’est aussi pourquoi [un plateau de deux minutes peut vraiment permettre de souffler](/blog/why-two-minute-puzzles-feel-good).']}
}, pullQuote: 'Le plateau peut être difficile. La relation n’a pas à l’être.', faqs: []
},
'minecraft-layered-discovery': {
title: 'Minecraft : laisser la découverte ajouter les couches', dek: 'Comment des débuts ouverts se sont enrichis de création, de survie, de fabrication, de multijoueur et de nouvelles plateformes.', imageAlt: 'Un paysage original construit en blocs avec une grotte, un établi et un lever de soleil', tags: ['Minecraft','découverte','conception de systèmes','succès d’un jeu'], intro: 'Les débuts de Minecraft racontent l’arrivée de couches au bon moment. La première version offrait un terrain ouvert pour creuser et construire ; les ajouts suivants ont enrichi cette liberté, ses enjeux et les façons de partager le résultat.', keyTakeaways: ['La rétrospective de Xbox Wire décrit un parcours de la construction Classic aux modes Creative et Survival, à la fabrication, au multijoueur et à davantage de plateformes.','Un système réussi peut grandir en approfondissant les actions du joueur plutôt qu’en les remplaçant à chaque mise à jour.','OutBrick applique ce principe à plus petite échelle : une action claire d’abord, puis des plateaux et chapitres plus expressifs.'], sections: {
'start-with-a-verb': {title: 'Commencer par une action que l’on ressent', paragraphs: ['La rétrospective des 15 ans publiée par Xbox Wire indique que Markus Persson a commencé Minecraft en 2009, inspiré par Infiniminer et Dungeon Keeper. La première version Classic permettait de creuser et de construire librement. Les modes Creative et Survival ont suivi, puis la fabrication, les wagonnets et la survie multijoueur ont été ajoutés en 2010.','La liste exacte de ces étapes vient du propre média éditorial de Microsoft : c’est une provenance utile, plutôt qu’un audit indépendant. Le schéma de conception reste clair : le jeu est parti d’une action immédiatement compréhensible, puis a créé de nouvelles raisons de l’utiliser.']},
'layers-that-reward-curiosity': {title: 'Des couches qui récompensent la curiosité', paragraphs: ['Une couche fonctionne lorsqu’elle fait revoir l’action d’origine autrement. La fabrication change le sens de la collecte. La survie change celui d’un lieu sûr. Le multijoueur change celui d’une construction quand une autre personne peut la voir.','Cela diffère de l’ajout de bruit. Les chapitres, étoiles, widgets, amis en briques et [le Voyage à travers 167 villages](/#journey) d’OutBrick gravitent autour de la même action : faire sortir une brique par la porte qui lui correspond. Chaque couche doit donner un contexte nouveau au mouvement sans demander d’apprendre un deuxième jeu.'], bullets: ['Approfondir une action existante','Laisser chacun choisir jusqu’où explorer le système','Rendre la progression visible sans transformer la découverte en devoirs','Permettre à des histoires personnelles de naître du jeu répété']},
 'the-value-of-a-personal-trace': {title: 'La valeur d’une trace personnelle', paragraphs: ['Le projet FabO du MIT a exploré comment des objets de jeu pouvaient être amenés dans le monde physique. Dans une étude exploratoire de 47 objets fabriqués issus de 33 jeux, les chercheurs ont constaté que les apprenants associaient à leurs créations des significations comme la fierté, l’expression créative personnelle, les ressources, le jeu prolongé et l’expérience partagée.','Peu de jeux ont besoin d’une imprimante 3D. L’idée plus générale est que le jeu prend davantage de sens lorsqu’il laisse quelque chose que l’on ressent comme sien. Dans OutBrick, un chapitre terminé, une mascotte préférée ou la troisième étoile d’un plateau rejoué peuvent servir de petite trace personnelle : le souvenir d’un moment plutôt que l’exigence d’un autre.']},
'grow-the-world-with-care': {title: 'Faire grandir l’univers avec soin', paragraphs: ['Le succès de Minecraft est souvent qualifié d’infini, mais ses débuts racontent quelque chose de plus pratique : offrir une action forte, laisser les joueurs y créer du sens et ajouter des systèmes qui récompensent le sens qu’ils créent déjà.','C’est à cette échelle qu’OutBrick peut utiliser la leçon. Une nouvelle fonctionnalité doit rendre le plateau plus OutBrick, pas ressembler à une deuxième application installée à l’intérieur.']}
}, pullQuote: 'Une couche fonctionne lorsqu’elle fait revoir l’action d’origine autrement.', faqs: []
},
'tetris-simple-rules-infinite-variation': {
title: 'Tetris : des règles simples toujours riches', dek: 'Un regard sur la contrainte, le rythme et la variété sans fin que peut contenir un tout petit ensemble de règles.', imageAlt: 'Des blocs-jouets géométriques colorés descendant vers une grille nette', tags: ['Tetris','conception de puzzles','création de jeux','règles'], intro: 'Un grand système de règles n’a pas besoin d’être vaste. Il doit produire assez de conséquences pour que la même action ait une autre saveur au tour suivant. Quarante ans plus tard, Tetris reste l’exemple le plus clair d’une contrainte qui devient expression.', keyTakeaways: ['L’histoire de The Tetris Company suit le jeu depuis une expérience sur Electronika 60 en 1984 jusqu’à un phénomène mondial sur de multiples plateformes.','Les règles simples gagnent en profondeur quand le temps, l’espace et l’engagement changent constamment le sens du prochain coup.','OutBrick traite chaque plateau comme un petit système laissant place à la planification, au rattrapage et à un chemin de résolution personnel.'], sections: {
'a-small-origin': {title: 'Une origine modeste', paragraphs: ['L’histoire officielle de Tetris situe la première version d’Alexey Pajitnov en 1984, sur un Electronika 60 à Moscou. Elle suit ensuite la découverte du jeu par Henk Rogers, les négociations pour les droits sur consoles portables et la décision de Nintendo d’inclure Tetris avec la Game Boy.','L’histoire du détenteur des droits mêle faits historiques et récit de marque : les ventes exactes doivent donc être considérées comme des chiffres rapportés par l’entreprise. La trame générale suffit à la leçon de conception : une idée compacte peut voyager si ses règles résistent au passage dans un nouveau contexte.']},
'constraint-creates-meaning': {title: 'La contrainte crée du sens', paragraphs: ['Une forme qui tombe ne devient urgente que parce que l’espace du plateau est limité. La même pièce peut être un cadeau, un problème ou une préparation selon ce qui s’y trouve déjà. Des règles simples créent de la variété lorsque les décisions précédentes changent le sens de la suivante.','Les briques coulissantes d’OutBrick fonctionnent de la même manière. « Amenez la brique à sa porte » est facile à dire. Ce qui intéresse, c’est que chaque coup change les couloirs ouverts, les briques qui se bloquent et les solutions encore possibles. La règle reste petite tandis que la situation évolue.']},
'rhythm-over-noise': {title: 'Le rythme avant le bruit', paragraphs: ['Les puzzles les plus mémorables ont souvent un rythme que l’on peut intégrer : voir, prévoir, s’engager, résoudre. Les systèmes supplémentaires peuvent être merveilleux, mais doivent soutenir ce rythme plutôt que l’interrompre.','C’est pourquoi OutBrick utilise les retours haptiques, la carte de réussite et les mouvements de victoire des amis comme une ponctuation. Le plateau porte la réflexion. Le reste de l’univers aide à ressentir le rythme d’une réussite.'], bullets: ['Une règle explicable en une phrase','Un état qui change après chaque décision','Un retour qui confirme au lieu de décorer','Une variété issue du contexte, pas de la confusion']},
 'the-next-piece': {title: 'La pièce suivante', paragraphs: ['Tetris reste vivant parce que la prochaine pièce pose toujours une nouvelle question. OutBrick en donne une version plus calme : parmi 2 000 plateaux vérifiés par un solveur, le suivant est une petite question différente, avec sa forme, son goulet d’étranglement et une nouvelle occasion de remarquer davantage que la dernière fois. Clés, serrures, briques gelées, convoyeurs et caisses arrivent progressivement, chacun offrant un angle neuf sur la même règle.','Simple ne veut pas dire superficiel. Cela veut dire que le joueur voit d’où vient la profondeur.']}
}, pullQuote: 'Simple ne veut pas dire superficiel. Cela veut dire que le joueur voit d’où vient la profondeur.', faqs: []
},
'daily-rituals-that-dont-demand-you': {
title: 'Pour des rituels quotidiens sans obligation', dek: 'Le jeu quotidien peut offrir un rythme bienvenu lorsqu’il invite l’attention sans faire de l’absence un échec.', imageAlt: 'Une tuile lumineuse de puzzle quotidien posée sur un petit calendrier-jouet', tags: ['jeux quotidiens','rituels','Wordle','jeu mobile'], intro: 'L’attrait d’un jeu quotidien ne tient pas seulement au puzzle. Il tient à la forme de l’invitation. Un bon rituel donne une petite identité à aujourd’hui sans faire ressentir l’absence d’hier comme une dette.', keyTakeaways: ['L’enquête 2024 de Pew montre que les jeux sont à la fois un divertissement fréquent et un espace social pour de nombreux adolescents.','La limite quotidienne et la liste de mots choisie de Wordle montrent la force de frontières délibérées.','La brique quotidienne d’OutBrick est conçue comme un bonjour, pas comme une série qui vous réprimande.'], sections: {
 'the-social-shape-of-play': {title: 'La forme sociale du jeu', paragraphs: ['Pew Research Center a constaté que 85 % des adolescents américains interrogés en 2023 jouaient aux jeux vidéo, et 41 % jouaient chaque jour. Parmi les joueurs adolescents, 72 % citaient le temps passé avec d’autres comme raison de jouer, et 47 % disaient avoir rencontré un ami en ligne grâce à un jeu.','Ces chiffres décrivent un échantillon d’adolescents américains, pas tous les joueurs ni tous les jeux. Ils montrent toutefois qu’un jeu « solo » peut s’inscrire dans un rythme social. On compare, recommande, se souvient et partage, même avec un téléphone dans la main et personne à côté.']},
 'why-a-limit-can-help': {title: 'Pourquoi une limite peut aider', paragraphs: ['Les articles sur le développement de Wordle décrivent plusieurs réductions volontaires : une liste plus courte de mots familiers, une structure d’une partie par jour inspirée des jeux de journaux et un format de résultat partageable que les joueurs ont contribué à populariser. Ces limites donnaient au jeu une forme sociale et faisaient de chaque puzzle un événement dont on pouvait discuter sans qu’un stock de parties à rattraper le gâche.','Une limite quotidienne peut donner au jeu l’allure d’un rituel plutôt que d’un onglet toujours ouvert. Mais elle doit être un cadre, pas une clôture. Après une journée manquée, l’expérience doit toujours être heureuse de vous retrouver.']},
 'the-outbrick-daily-brick': {title: 'La brique quotidienne d’OutBrick', paragraphs: ['La brique quotidienne est notre plus petite invitation récurrente : le premier plateau terminé chaque jour rapporte cent pièces en plus de sa récompense habituelle. Elle apporte un peu de lumière matinale à l’accueil sans devenir l’unique raison d’ouvrir l’application. [Le Voyage](/#journey) avance à votre rythme, continue à générer des plateaux après le deux-millième et ne retire pas aux autres jours leur valeur lorsque vous en manquez un.','Ce choix touche à l’adéquation à la vie. Les recherches sur le jeu et le bien-être suggèrent que le contexte et la valeur perçue comptent davantage que la réduction du temps de jeu à un score unique. Une fonctionnalité quotidienne doit aider à marquer un moment, pas mesurer la valeur de quelqu’un.']},
 'ritual-without-obligation': {title: 'Un rituel sans obligation', paragraphs: ['Ce qui distingue un rituel d’une obligation, c’est que la personne reste aux commandes. Vous choisissez le moment, la durée et le sens. La conception peut offrir un petit repère lumineux sans vous obliger à négocier avec lui.','OutBrick veut être le jeu qui dit « un plateau vous attend si vous en avez envie ». C’est une raison suffisante pour revenir. Pour l’autre versant de la question, consultez [comment les jeux deviennent des habitudes](/blog/how-games-become-habits).']}
}, pullQuote: 'Un bon rituel donne une petite identité à aujourd’hui sans faire ressentir l’absence d’hier comme une dette.', faqs: []
},
'color-shape-accessibility': {
title: 'La couleur ne doit jamais être le seul indice', dek: 'Associer couleur, forme, texte et autres signaux permet de garder un plateau lisible pour davantage de joueurs.', imageAlt: 'Des briques de puzzle brillantes portant des formes gravées distinctes en plus de leurs couleurs', tags: ['accessibilité','vision des couleurs','conception inclusive','jeux de puzzle'], intro: 'La couleur est expressive. Elle est aussi peu fiable comme seule source de vérité. Les puzzles les plus accueillants l’utilisent pour embellir un motif, puis renforcent le sens par la forme, le texte, l’espacement ou le mouvement.', keyTakeaways: ['Les recommandations WCAG sur l’utilisation de la couleur précisent qu’elle ne doit pas être le seul moyen visuel de transmettre une information.','Les recommandations d’accessibilité des jeux de Microsoft préconisent des symboles et des motifs en plus de la couleur, ainsi que des options réglables.','Les glyphes pour le daltonisme d’OutBrick sont activés par défaut ; teinte, forme et tenons portent tous l’identité d’une brique.'], sections: {
'color-is-a-great-accent': {title: 'La couleur : un bel accent, pas un gardien', paragraphs: ['Les recommandations du W3C pour le critère de succès 1.4.1 sont directes : la couleur ne doit pas être le seul moyen visuel de distinguer une information. La raison est pratique. Nous ne voyons pas tous les couleurs de la même façon, et une information peut disparaître si elle n’est codée que par la teinte.','Un produit n’a pas à devenir gris pour respecter cela. La couleur peut continuer à servir la hiérarchie, l’ambiance et l’accentuation, tandis qu’un autre signal porte la règle que le joueur ne doit pas manquer.']},
'symbols-make-the-board-clearer': {title: 'Les symboles clarifient le plateau pour tous', paragraphs: ['La présentation de l’accessibilité des jeux de Microsoft recommande de communiquer l’information de plusieurs façons : une image avec du texte, ou un symbole avec une couleur. Elle demande aussi de vérifier si le jeu reste jouable sans son, sur un écran noir et blanc et après une longue pause.','Ces questions sont utiles pour tout puzzle, au-delà d’une liste de contrôle d’accessibilité. Un joueur qui peut confirmer une correspondance par la forme n’accomplit pas un travail supplémentaire : il dispose d’un deuxième chemin vers la même compréhension.']},
'how-outbrick-does-it': {title: 'Comment OutBrick procède', paragraphs: ['OutBrick transmet l’identité de chaque brique par trois canaux simultanés : teinte, forme et tenons. Le mode daltonisme est activé par défaut et applique un glyphe distinct à chaque brique et porte, pour que la couleur ne soit jamais l’unique critère de tri. Le système visuel reste ludique parce que ces signaux font partie du langage du jouet : de petites marques lisibles avec les yeux et la mémoire.','Cette réflexion dépasse le plateau. Chaque brique est aussi un élément VoiceOver qui annonce sa couleur, sa forme et sa position ; l’agrandissement du texte s’applique partout et Réduire les animations est respecté dans tout le jeu. Nous avons toujours besoin de tests avec des joueurs aux besoins d’accès variés : la documentation ne remplace pas leurs retours. La [page d’accessibilité](/accessibility) décrit ce qui est disponible aujourd’hui.']},
 'accessibility-is-quality': {title: 'L’accessibilité est un signe de qualité', paragraphs: ['La conception inclusive améliore souvent l’expérience de base, car elle oblige l’équipe à se demander si le jeu communique ou se contente de décorer. Cela conduit à un contraste plus fort, des retours plus clairs, de meilleures options et moins de moments où l’on doit deviner le sens de l’écran.','Dans un puzzle, la clarté n’est pas une concession. C’est la matière de la difficulté. Si le joueur ne peut pas lire la règle avec fiabilité, il résout l’interface au lieu de résoudre le plateau.']}
}, pullQuote: 'Si le joueur ne peut pas lire la règle avec fiabilité, il résout l’interface au lieu de résoudre le plateau.', faqs: []
},
'when-to-play-and-when-to-pause': {
title: 'Quand jouer, et quand poser le téléphone', dek: 'Un guide honnête pour faire une place aux jeux autour du sommeil, de l’attention et d’une vraie journée.', imageAlt: 'Un petit plateau de puzzle près d’une horloge de chevet lumineuse et d’un livre qui se ferme', tags: ['pratique de jeu saine','sommeil','habitudes de jeu','bien-être'], intro: 'Un bon jeu doit parler honnêtement des limites du jeu. Le plaisir compte, tout comme le sommeil, le travail, les relations et la capacité de s’arrêter quand on le souhaite.', keyTakeaways: ['Des études contrôlées relient le jeu stimulant avant le coucher à un endormissement retardé dans des échantillons et contextes précis.','Les méta-analyses portent sur le jeu problématique et le sommeil, pas sur le jeu récréatif ordinaire.','L’Organisation mondiale de la Santé définit le trouble du jeu vidéo par une perte de contrôle et une altération significative du fonctionnement, pas par un simple nombre d’heures.'], sections: {
'sleep-is-a-real-design-constraint': {title: 'Le sommeil est une vraie contrainte de conception', paragraphs: ['Dans une étude contrôlée auprès d’adolescents, jouer cinquante minutes avant le coucher retardait l’endormissement par rapport au visionnage d’un DVD. Une autre expérience de séance prolongée, avec des jeux différents, a observé des changements d’efficacité du sommeil et du rappel de mots le lendemain matin. Ces résultats sont propres aux conditions étudiées, mais soutiennent une limite raisonnable : le jeu intense ou stimulant juste avant le coucher ne convient peut-être pas à tout le monde.','Une réponse honnête consiste à faciliter l’arrêt, à ne plus prétendre qu’une boucle tard dans la nuit n’a aucun coût et à donner assez d’informations pour choisir. Étiqueter tous les jeux comme nuisibles n’aide personne.']},
'problematic-is-not-the-same-as-ordinary': {title: 'Problématique ne signifie pas ordinaire', paragraphs: ['Une revue systématique et méta-analyse a trouvé une association entre le jeu problématique et une durée de sommeil plus courte, avec une variation considérable entre les études. Cette variation compte, car les données concernent une pratique liée à une altération du fonctionnement, pas tous ceux qui jouent pour le plaisir.','L’Organisation mondiale de la Santé décrit le trouble du jeu vidéo par un contrôle altéré, une priorité croissante accordée au jeu et sa poursuite malgré des conséquences négatives, d’une gravité suffisante pour causer une altération significative du fonctionnement, généralement manifeste pendant au moins douze mois. C’est une définition clinique, pas un synonyme de « une fois, j’ai joué plus longtemps que prévu ».']},
'our-pause-friendly-defaults': {title: 'Nos réglages qui accueillent les pauses', paragraphs: ['OutBrick n’a aucune série à défendre ni rien qui expire discrètement pendant votre absence. Terminer un plateau et s’arrêter là est l’action la moins coûteuse du jeu : elle ne coûte rien, et la carte de réussite offre une fin naturelle plutôt qu’un passage vers la séance suivante. On peut manquer la brique quotidienne sans que demain devienne une punition, et chaque plateau commence avec une annulation gratuite pour qu’un mauvais coup soit une occasion d’apprendre plutôt qu’une erreur à payer.','Un coût mérite d’être annoncé clairement : un essai qui se termine sans réussite, y compris l’abandon d’un plateau où vous avez déjà joué un coup, consomme une vie. Vous en avez cinq, huit avec le Brick Pass, et une revient automatiquement toutes les trente minutes. C’est une règle du genre que nous avons conservée, car sans elle la limite de coups n’aurait aucun sens. Rien d’autre ne consomme de vie : ni jouer, ni terminer, ni annuler, ni ouvrir un niveau pour le regarder puis changer d’avis. La liste complète figure sur l’accueil, sous [ce que cela coûte](/#fair). Le but est de faire d’« encore un plateau » un choix, pas un piège caché dans l’interface.'], bullets: ['S’arrêter après une réussite sans perdre sa place','Une annulation gratuite sur chaque plateau, toujours','Les vies reviennent seules, une toutes les demi-heures','Laisser les réglages soutenir le contexte du joueur']},
'a-useful-question': {title: 'Une question utile à se poser', paragraphs: ['Au lieu de demander si un certain nombre de minutes est universellement bon ou mauvais, demandez-vous : « Cette séance s’accorde-t-elle avec le reste de ma vie aujourd’hui ? » Si la réponse est non — fatigue, manque de sommeil ou impression de ne pas pouvoir s’arrêter — le geste bienveillant est de faire une pause et de modifier les conditions autour du jeu.','OutBrick est un jeu, pas un clinicien. Si le jeu cause une détresse importante ou perturbe la vie quotidienne, parlez-en à un professionnel qualifié. Un jeu réfléchi doit laisser place à cette phrase.']}
}, pullQuote: 'Le but est de faire d’« encore un plateau » un choix, pas un piège caché dans l’interface.', faqs: [{question: 'OutBrick recommande-t-il une limite quotidienne précise ?', answer: 'Non. Les personnes et les contextes diffèrent. Nous recommandons de prêter attention au sommeil, aux obligations et au sentiment de garder la maîtrise de son jeu.'},{question: 'Le trouble du jeu vidéo signifie-t-il jouer chaque jour ?', answer: 'Non. La définition de l’OMS porte sur la perte de contrôle, la priorité sur d’autres activités, la poursuite malgré des conséquences négatives et une altération significative du fonctionnement dans la durée.'}]
},
'kinder-difficulty-curve': {
title: 'Construire une difficulté plus bienveillante', dek: 'Le défi doit étirer l’attention du joueur sans fragiliser sa relation avec le jeu.', imageAlt: 'Un chemin ascendant de petits plateaux avec des étapes faciles et difficiles', tags: ['conception de la difficulté','flow','création de jeux','accessibilité'], intro: 'La difficulté n’est pas un escalier qui ne ferait que monter. C’est une conversation entre le savoir-faire actuel du joueur, la prochaine question du jeu et les retours qui expliquent ce qui s’est passé.', keyTakeaways: ['Les recherches orientées GameFlow soulignent l’équilibre défi-compétences, les objectifs clairs, les retours, le contrôle et l’immersion.','Une petite étude de jeux de rééducation par le mouvement a trouvé des différences individuelles significatives de flow et de contrôle perçu.','OutBrick utilise des plateaux vérifiés par un solveur, des outils de rattrapage et une limite de coups plutôt qu’une horloge pour rendre le défi modulable.'], sections: {
'challenge-and-skill-need-each-other': {title: 'Défi et compétence ont besoin l’un de l’autre', paragraphs: ['Une revue de systèmes de rééducation par le jeu utilise GameFlow comme prisme de conception : concentration, défi, compétence, contrôle, objectifs clairs, retours, immersion et interaction sociale. Elle décrit la difficulté adaptative comme un moyen d’éviter qu’une tâche devienne si facile qu’elle ennuie ou si difficile qu’elle angoisse.','L’idée dépasse la rééducation. Un joueur ne vit pas une abstraite « difficulté de niveau 20 ». Il vit une relation entre ce que demande le plateau et ce que l’interface lui a appris à remarquer.']},
'one-curve-does-not-fit-everyone': {title: 'Une seule courbe ne convient pas à tous', paragraphs: ['Une étude transversale de 2025 sur une tâche de rééducation avec Kinect a trouvé un flow global inférieur chez les participants plus âgés que chez les plus jeunes, avec le plus grand écart dans le sentiment de contrôle. La tâche et l’échantillon étaient particuliers : l’étude ne justifie donc pas des suppositions fondées sur l’âge pour tous les joueurs.','Elle soutient néanmoins un principe plus général : familiarité, capacités motrices, confiance, vitesse de traitement et besoins d’accès peuvent modifier la sensation d’un même défi. Une bonne courbe accueille ces différences au lieu de les considérer comme des échecs du joueur.']},
'our-tools-for-a-kinder-curve': {title: 'Nos outils pour une courbe plus douce', paragraphs: ['Un solveur a terminé les 2 000 plateaux d’OutBrick avant leur publication : le jeu peut demander de planifier sans demander accidentellement l’impossible. La limite de coups de chaque plateau est vérifiée par rapport au chemin réellement trouvé par le solveur : aucun ne dispose d’une marge plus courte que sa solution prouvée. Lorsqu’une position se bloque, le panneau de rattrapage le dit et propose une suite ; son annulation est gratuite et indépendante de la réserve d’annulations, car un plateau qui s’est bloqué relève du jeu, pas du joueur. La pression est une limite de coups, jamais une horloge : le minuteur Rush facultatif a été retiré, et aucun compte à rebours n’existe dans le jeu.','Cela ne supprime pas le défi. Cela sépare la friction utile de la friction accidentelle, pour que le joueur consacre son attention à l’idée du puzzle plutôt qu’à se défendre de l’interface.'], bullets: ['Une résolution vérifiée avant la publication','Une annulation qui enseigne au lieu de réprimander','Une sortie gratuite lorsque l’état est réellement bloqué','La pression d’une limite de coups, jamais d’une horloge']},
'difficulty-as-an-invitation': {title: 'La difficulté comme invitation', paragraphs: ['La courbe la plus juste donne une raison de réessayer assez précise pour savoir quoi faire. « J’avais presque ouvert le couloir » invite mieux que « le jeu veut que je répète sans fin ». Le retour doit transformer un échec en information.','Voilà la courbe que nous voulons : des plateaux plus expressifs, des outils qui laissent le contrôle au joueur et un univers qui célèbre l’essai autant que la réussite.']}
}, pullQuote: '« J’avais presque ouvert le couloir » invite mieux que « le jeu veut que je répète sans fin ».', faqs: []
},
'cozy-progress-without-grind': {
title: 'Stardew Valley : l’art d’une progression douce', dek: 'Une histoire de patience, de progression visible et de générosité qui ne supprime pas toute résistance.', imageAlt: 'Un petit jardin, une maison et un chemin sinueux illustrant une progression douce au lever du soleil', tags: ['Stardew Valley','jeux cosy','progression','conception de jeux'], intro: 'Le jeu cosy est moins une liste de caractéristiques qu’une relation au temps. On voit ce que l’on fait grandir, on choisit le rythme de la prochaine tâche et on ressent le retour comme un plaisir plutôt qu’une dette.', keyTakeaways: ['Stardew Valley est un exemple utile d’itération patiente portée par son créateur et de progression facile à lire.','La douceur a besoin de texture : choix, limites, petites surprises et raison de s’intéresser à la suite.','OutBrick emprunte la sensation d’un retour accueillant tout en gardant son langage de puzzle compact.'], sections: {
 'the-work-behind-the-welcome': {title: 'Le travail derrière l’accueil', paragraphs: ['Entrer dans Stardew Valley paraît souvent sans effort, mais cet accueil résulte d’un travail durable. Dans une précision sur le développement du jeu, son créateur Eric Barone écrivait avoir été la seule personne à travailler sur Stardew Valley pendant ses quatre ans et demi de développement, l’éditeur ne contribuant qu’au réseau multijoueur. C’est un témoignage à la première personne, à lire comme une déclaration du créateur plutôt qu’une histoire complète de production, mais il clarifie l’ampleur de l’expérience solo.','Pour un petit studio, la leçon n’est pas « travailler seul ». C’est qu’une expérience chaleureuse peut résulter de milliers de décisions délibérées et lisibles. Un accueil en douceur reste une réussite technique et éditoriale.']},
'progress-you-can-feel': {title: 'Une progression que l’on ressent', paragraphs: ['Une progression douce a une forme visible. Une graine devient plante, une pièce devient vôtre, un chemin s’ouvre ou une routine familière gagne une possibilité. Nul besoin d’une explosion de récompenses pour comprendre que votre attention a compté.','Cette clarté rejoint le modèle motivationnel de compétence et d’autonomie : les joueurs veulent se sentir capables et maîtres de leurs actions. Les recherches ne disent pas que tout système cosy crée du bien-être. Elles offrent un vocabulaire utile pour comprendre pourquoi une progression conçue avec soin peut satisfaire.']},
'gentle-does-not-mean-empty': {title: 'Doux ne veut pas dire vide', paragraphs: ['Un jeu s’aplatit si « cosy » signifie que rien ne peut surprendre le joueur ni lui résister. La meilleure version garde de la friction : une saison change, une ressource est limitée, un voisin a un horaire ou un puzzle demande un second regard. Cette friction a du sens parce que le jeu vous donne le temps et les outils pour répondre.','Pour OutBrick, cela signifie qu’un plateau peut être bienveillant sans être résolu à votre place. Les règles restent fermes, la limite de coups réelle et la solution méritée ; la première annulation gratuite évite qu’une expérience devienne une punition. On vous propose un petit problème clairement délimité, pas un écran vide déguisé en détente.'], bullets: ['Rendre la progression visible sans bruit','Commencer le retour par la reconnaissance','Garder assez de résistance pour que les choix comptent','Utiliser les outils de rattrapage pour protéger la curiosité']},
'a-welcoming-return': {title: 'Concevoir un retour accueillant', paragraphs: ['Les meilleurs jeux cosy ne conçoivent pas seulement la première séance. Ils conçoivent la sensation de rouvrir le jeu après une semaine chargée. Le joueur se rappelle l’univers, voit une étape suivante attrayante et décide si aujourd’hui sera une visite de deux minutes ou un séjour plus long.','C’est ce qu’OutBrick veut faire sien : un plateau qui vous rejoint là où vous êtes, un village du [Voyage](/#journey) resté là où vous l’avez laissé et une progression toujours vôtre, dans votre iCloud, sur tous les appareils où vous vous connectez.']}
}, pullQuote: 'Un accueil en douceur reste une réussite technique et éditoriale.', faqs: []
},
'hades-run-keeps-learning': {
title: 'Hades : une tentative qui continue à apprendre', dek: 'Ce que le succès de l’accès anticipé de Supergiant enseigne sur l’itération, l’élan narratif et des essais réellement différents.', imageAlt: 'Un aventurier solitaire suit des chemins lumineux ramifiés dans un monde souterrain cramoisi et indigo', tags: ['Hades','accès anticipé','itération','conception de roguelikes'], intro: 'Une nouvelle tentative n’est passionnante que si elle fait avancer l’information. Hades a rendu ce principe visible : une partie pouvait finir, mais la relation du joueur à l’univers, au récit et à ses décisions continuait d’évoluer.', keyTakeaways: ['Supergiant décrit Hades comme conçu dès le départ pour l’accès anticipé, avec les retours de la communauté intégrés au processus.','Une partie répétée exige plus qu’une variation aléatoire : mémoire, interprétation et raison d’essayer une autre approche.','OutBrick en applique une version plus petite : chaque plateau doit enseigner un motif sans exiger une longue campagne.'], sections: {
'early-access-as-a-design-loop': {title: 'L’accès anticipé comme boucle de conception', paragraphs: ['La FAQ de Hades de Supergiant indique que le jeu a été conçu dès le départ pour l’accès anticipé. Le studio décrit l’objectif de créer avec sa communauté et relie la structure modulaire du jeu et du récit à cette approche. C’est le récit du studio, mais il est précieux précisément parce qu’il explique l’intention de production derrière l’expérience achevée.','La boucle se transpose facilement : publier une portion cohérente, écouter ce que les joueurs comprennent réellement, puis faire répondre la suivante à une meilleure question. Les retours indiquent où la conception communique et où elle demande de deviner ; ils ne sont pas un vote sur chaque détail.']},
'the-run-remembers': {title: 'La partie garde une mémoire', paragraphs: ['Hades transforme l’échec en changement de contexte. Une partie peut révéler une interaction d’arme, un moment avec un personnage, un choix de ressource ou un itinéraire qui modifie le sens de la tentative suivante. On ne relance pas seulement les mêmes dés : on emporte un meilleur modèle du système.','Voilà pourquoi « aléatoire » ne suffit pas. La variation devient satisfaisante lorsqu’on la relie à un vocabulaire qui grandit. Un petit puzzle peut le faire avec une nouvelle disposition de portes, un goulet découvert ou une solution qui ne devient évidente qu’après le premier essai.']},
'narrative-keeps-the-door-open': {title: 'Le récit garde la porte ouverte', paragraphs: ['Les documents officiels de Hades décrivent un récit pouvant être livré par épisodes durant l’accès anticipé. L’histoire offrait une réponse douce à « pourquoi revenir ? ». Elle donnait à la partie suivante un horizon émotionnel même lorsque son résultat mécanique était incertain.','OutBrick n’est pas un roguelike narratif et ne doit pas prétendre l’être. Son retour est plus calme : le plateau fait remarquer une règle, le suivant la présente autrement et l’état de réussite reste assez compréhensible pour que l’apprentissage survive à une courte séance.']},
'designing-the-next-attempt': {title: 'Concevoir la tentative suivante', paragraphs: ['Un jeu répétable doit répondre à trois questions après un échec : qu’est-ce qui a changé, qu’ai-je appris et que puis-je essayer ensuite ? Si la seule réponse est « répéter jusqu’à améliorer les chiffres », la boucle emprunte du temps au lieu de mériter l’attention.','Le plateau d’OutBrick est assez petit pour rester en mémoire. Une mauvaise piste peut devenir un indice plutôt qu’une cicatrice. Une boucle compacte laisse moins à oublier et donne plus de sens à la décision restante. Lorsqu’un essai finit sans réussite, il coûte une vie, et [l’accueil explique exactement le fonctionnement des vies](/#fair).'], bullets: ['Rendre le résultat d’un essai lisible','Faire avancer la connaissance même quand le plateau est réinitialisé','Proposer une prochaine expérience précise','Permettre l’arrêt une fois la boucle achevée']}
}, pullQuote: 'Une nouvelle tentative n’est passionnante que si elle fait avancer l’information.', faqs: []
},
'celeste-assist-mode-accessibility': {
title: 'Celeste : l’assistance au service de la conception', dek: 'Une aide facultative peut préserver le cœur du défi tout en donnant à davantage de joueurs un chemin pour y accéder.', imageAlt: 'Un paysage montagneux calme avec plusieurs chemins clairs vers le sommet et de petits grimpeurs génériques', tags: ['Celeste','mode assistance','accessibilité','conception de la difficulté'], intro: 'L’accessibilité ne promet pas que tous vivront un jeu exactement de la même manière. Elle consiste à rendre son invitation centrale accessible par plusieurs chemins.', keyTakeaways: ['Le mode assistance facultatif de Celeste est un exemple très discuté de respect du choix face au défi.','Des recherches CHI récentes soulignent les connaissances communautaires, les expériences personnalisables et le jeu non conventionnel pour les joueurs handicapés.','OutBrick traite les outils d’aide comme une part du langage du jeu plutôt que comme la preuve d’un échec.'], sections: {
 'the-core-can-stay-intact': {title: 'Le cœur peut rester intact', paragraphs: ['Le mode assistance de Celeste convainc parce qu’il n’exige pas de prétendre que la difficulté n’a aucun sens. Il offre des façons facultatives de modifier les conditions de jeu, afin que la montagne reste un lieu d’attention et de découverte même lorsque le rythme ou la vitesse par défaut ne convient pas.','Cette distinction compte. Une option d’aide n’est pas une version de seconde classe. Elle permet de choisir les conditions dans lesquelles on participe à l’idée qui importe au jeu.']},
 'what-disabled-players-teach-designers': {title: 'Ce que les joueurs handicapés enseignent aux concepteurs', paragraphs: ['Martinez, Froehlich et Fogarty ont interrogé treize joueurs handicapés sur l’adoption des jeux et décrit des étapes de découverte, d’évaluation et d’adaptation. Leurs recommandations comprennent de meilleures ressources communautaires, un accès créé socialement, des expériences personnalisables et le soutien du jeu non conventionnel. L’échantillon est petit et qualitatif, mais c’est justement sa précision qui compte : les besoins d’accès apparaissent dans des décisions réelles, pas seulement dans une liste de contrôle.','La recherche remet aussi en question une conception étroite de la maîtrise. Un joueur peut être très engagé avec des commandes réattribuées, une vitesse réduite, un indice visuel, un guide ou une manière de bouger jamais imaginée par le concepteur. Le but est une participation autonome, pas l’exécution du parcours préféré du créateur.']},
'more-than-one-signal': {title: 'Plus d’un signal', paragraphs: ['Le W3C conseille de ne pas faire de la couleur le seul moyen visuel de transmettre une information. Les recommandations de Microsoft pour les jeux défendent aussi l’association de signaux et la prise en compte du jeu sans son, sur écran monochrome ou après une longue pause.','Dans OutBrick, formes, tenons, espacement, contraste et mouvement renforcent le langage des couleurs. C’est mieux pour ceux qui ne peuvent pas se fier aux teintes, mais aussi pour tous lorsque le plateau s’explique d’un coup d’œil.']},
'support-is-a-design-material': {title: 'L’aide se travaille dans la conception', paragraphs: ['Les options d’accessibilité les plus utiles sont faciles à trouver, réversibles et sans honte. Elles se situent près de la décision concernée, expliquent leur effet et permettent d’ajuster l’expérience quand le contexte change.','C’est la norme visée par OutBrick. Une [courbe de difficulté plus bienveillante](/blog/kinder-difficulty-curve), un rattrapage clair et un mode daltonisme actif dès le premier lancement ne décorent pas le puzzle. Ils permettent au puzzle de rester un puzzle pour davantage de personnes.'], bullets: ['Associer couleur, forme et motif','Garder les options d’aide visibles et réversibles','Tester avec ceux qui utilisent ces options','Reconnaître le jeu non conventionnel comme valable']}
}, pullQuote: 'Une option d’aide n’est pas une version de seconde classe.', faqs: [{question: 'Le mode assistance rend-il Celeste plus facile ?', answer: 'Il permet d’ajuster certaines conditions de jeu. L’idée essentielle est que le joueur choisit son chemin, plutôt que de traiter l’accessibilité comme un jeu séparé.'},{question: 'Quelles options d’accessibilité propose OutBrick ?', answer: 'Le mode daltonisme est actif par défaut et appose un glyphe sur chaque brique et porte. Chaque brique est un élément VoiceOver, l’agrandissement du texte s’applique partout, Réduire les animations est respecté et il n’y a aucune horloge. La [page d’accessibilité](/accessibility) donne la liste complète.'}]
},
'sims-stories-systems-tell': {
title: 'Les Sims : les histoires que racontent les systèmes', dek: 'Une réussite durable fondée sur les récits des joueurs, une résistance ludique et un jeu qui n’écrit pas chaque ligne à leur place.', imageAlt: 'Un quartier en coupe à l’heure dorée, où pièces, routines, objets et chemins forment des histoires quotidiennes', tags: ['Les Sims','histoires émergentes','conception de systèmes','autonomie du joueur'], intro: 'Les Sims rappelle qu’un jeu peut créer des histoires mémorables sans scénariser tous les moments. Offrez un système lisible, un peu de résistance et de la place pour décider : les histoires commencent à appartenir aux joueurs.', keyTakeaways: ['L’attrait durable des Sims vient de la place centrale donnée aux histoires créées par les joueurs.','Les systèmes ont besoin de conséquences lisibles et d’une résistance ludique pour produire des histoires plutôt que du bruit.','OutBrick utilise une petite forme de conception émergente : quelques règles composent un plateau que le joueur peut faire sien.'], sections: {
 'the-player-is-the-author': {title: 'Le joueur est l’auteur', paragraphs: ['Dans une rétrospective de 25 ans, Xbox Wire décrit l’idée centrale des Sims comme l’histoire du joueur, le jeu y opposant une résistance humoristique. Ce récit éditorial proche des acteurs du secteur n’est pas une évaluation indépendante de la série, mais il saisit la promesse qui l’a rendue compréhensible à des générations : le système fournit la situation, le joueur le sens.','Cela diffère de l’offre d’un immense bac à sable en espérant qu’il se passe quelque chose. L’expression personnelle a besoin de matériaux compréhensibles. On doit savoir ce qu’un choix pourrait changer, même si l’histoire finale surprend.']},
'pushback-makes-a-story': {title: 'La résistance crée une histoire', paragraphs: ['Un système sans friction produit une liste de tâches. Un système hostile produit de la fatigue. La résistance ludique se trouve entre les deux : le plan peut dérailler, mais la conséquence reste assez lisible pour devenir un souvenir.','Les recherches sur la motivation aident à comprendre pourquoi. L’autonomie n’est pas l’absence de règles, mais le sentiment que vos décisions vous appartiennent dans un univers qui répond. Le lien peut venir des personnages, des autres joueurs ou du public imaginé auquel vous raconterez ensuite l’histoire.']},
'small-systems-can-still-emerge': {title: 'Les petits systèmes peuvent aussi faire émerger', paragraphs: ['OutBrick ne simule pas un quartier. Son petit système est le plateau : une brique occupe un couloir, une porte attend une forme correspondante et un mouvement change les possibilités suivantes. L’histoire est une phrase plutôt qu’un roman : « J’ai vu l’ouverture, choisi le long chemin et dû annuler deux coups plus tard. »','Cette phrase suffit à créer un sentiment d’appropriation. Le plateau offre une série de décisions dont le joueur peut se souvenir comme siennes.'], bullets: ['Donner un petit vocabulaire d’actions','Garder les conséquences lisibles','Permettre une issue surprenante sans cacher la règle','Faire ressentir la réussite finale comme personnelle']},
'design-for-the-story-after': {title: 'Concevoir pour l’histoire d’après', paragraphs: ['La réussite d’un système se mesure souvent à ce que disent les joueurs après la séance. « J’ai construit une maison étrange », « mon voisin est devenu mon rival » ou « j’ai trouvé le seul couloir possible » montrent que le joueur interprète la conception au lieu de seulement la consommer.','OutBrick vise cette petite empreinte. Le plateau suivant doit être nouveau, mais le joueur doit repartir avec un moment clair à emporter dans sa prochaine conversation, son trajet ou sa pause tranquille.']}
}, pullQuote: 'Un système sans friction produit une liste de tâches. Un système hostile produit de la fatigue.', faqs: []
},
'pokemon-go-power-of-place': {
title: 'Pokémon GO et le pouvoir des lieux', dek: 'Ce que le jeu géolocalisé révèle du mouvement, du lien social et de la place du monde extérieur dans le jeu.', imageAlt: 'Un explorateur générique suit un chemin lumineux dans un parc urbain vers un point de repère', tags: ['Pokémon GO','jeux géolocalisés','jeu social','attachement aux lieux'], intro: 'Certains jeux donnent une seconde couche à un lieu. Un parc devient parcours, un monument devient rendez-vous et une promenade ordinaire reçoit un peu plus d’attention. La meilleure conception géolocalisée ajoute du sens au monde sans prétendre que l’écran est tout le monde.', keyTakeaways: ['Les recherches sur Pokémon GO relient le jeu à des motivations comme l’interaction sociale et l’exploration, avec des résultats dépendant du contexte et de l’échantillon.','La conception liée aux lieux peut faire du mouvement et de la découverte locale une matière de jeu.','OutBrick est conçu pour jouer sur place, mais emprunte le principe d’une petite couche mémorable ajoutée au quotidien.'], sections: {
 'the-world-becomes-the-board': {title: 'Le monde devient le plateau', paragraphs: ['L’étude de Wang et Hsieh sur Pokémon GO examine les relations entre personnes, environnements et jeu en réalité augmentée géolocalisé. Ce cadre est utile, car une grande partie de la nouveauté du jeu tient à la façon dont la géographie familière devient un espace d’action, au-delà de la collection. Un coin de rue, un sentier ou un espace public peut offrir une possibilité nouvelle lorsque le jeu y dirige l’attention.','Le défi consiste à ajouter une couche sans effacer le lieu lui-même. Un jeu doit encourager l’attention à la rue, aux personnes qui la partagent et aux limites pratiques du milieu, pas transformer chaque espace public en point de ressources invisible.']},
 'why-people-keep-walking': {title: 'Pourquoi on continue à marcher', paragraphs: ['Une étude fondée sur l’approche des usages et gratifications a examiné pourquoi on joue à Pokémon GO et comment ces motivations se relient à la poursuite de l’usage. Elle porte sur un jeu en réalité augmentée et ses participants interrogés, pas sur tous les comportements, mais renforce une idée pratique : la fidélité peut venir du sens ajouté à une activité, pas seulement d’un calendrier de récompenses.','Exploration, compétence et contact social peuvent se mêler. On marche plus loin parce qu’un itinéraire intéresse, qu’un ami attend ou que le jeu rend le quartier familier nouvellement lisible.']},
 'social-benefits-have-a-place': {title: 'Les bénéfices sociaux ont un lieu', paragraphs: ['Une étude indexée dans PubMed, intitulée Enhanced Community Through Augmented Reality, rapporte des résultats d’enquête sur les rencontres, les nouveaux lieux visités et la fréquentation de commerces locaux via Pokémon GO. Ce sont des associations autodéclarées, pas la preuve que le jeu a causé chaque résultat. Elles montrent toutefois pourquoi le lieu peut être une matière de conception sociale.','Une couche sociale n’implique pas nécessairement discussion vocale ou classement. Ce peut être un parcours partagé, un repère familier, un récit de la promenade ou la simple reconnaissance que d’autres prêtent attention au même monde.']},
 'outbrick-and-the-ordinary': {title: 'OutBrick et l’ordinaire', paragraphs: ['OutBrick ne vous demande d’aller nulle part. Son lieu est le petit intervalle : le quai, la table basse, la minute avant une réunion ; il fonctionne hors ligne, donc le tunnel n’importe pas. Le lien relève de l’attitude plutôt que des mécaniques. Un bon jeu peut rendre un contexte ordinaire plus intentionnel en donnant à l’attention une forme claire et délimitée. Nous en parlons davantage dans [Le puzzle des trajets](/blog/commuter-puzzle-two-minute).','Que le plateau soit au parc ou chez soi, l’invitation reste la même : remarquer une chose, faire un choix et laisser le monde un peu plus facile à retrouver.']}
}, pullQuote: 'La meilleure conception géolocalisée ajoute du sens au monde sans prétendre que l’écran est tout le monde.', faqs: []
},
'games-teach-curiosity-without-lecture': {
title: 'Quand le jeu enseigne la curiosité sans leçon', dek: 'Comment les systèmes interactifs invitent à expérimenter, et ce que les travaux du MIT sur l’apprentissage par la création suggèrent sur l’autonomie avant l’explication.', imageAlt: 'Un jeune joueur explore des indices réactifs dans une prairie ensoleillée menant à un observatoire cinétique', tags: ['jeux d’apprentissage','curiosité','MIT','conception de jeux'], intro: 'Enseigner dans un jeu n’est pas y placer une leçon. Il faut une question qui mérite d’être posée, un système qui répond honnêtement et assez de place pour formuler une hypothèse avant l’arrivée de l’explication.', keyTakeaways: ['Le récit du MIT sur l’apprentissage de fabrication par le jeu met l’accent sur créer, tester et partager plutôt que recevoir passivement des consignes.','La curiosité grandit quand les expériences sont sûres et leurs résultats lisibles.','OutBrick utilise de petits puzzles pour inviter à remarquer des relations, pas comme des tests au barème caché.'], sections: {
'curiosity-starts-with-a-question': {title: 'La curiosité commence par une question', paragraphs: ['Un jeu enseigne lorsque le joueur veut savoir ce qui va suivre. Ce désir peut naître d’une discordance visible, d’un objet réactif ou d’une règle assez simple à tester. Le joueur n’attend pas la fin du tutoriel : il construit déjà un modèle.','Ce modèle peut être faux. Cela fait partie de sa valeur. Une erreur sans danger apporte un nouvel élément de preuve et garde la création du côté du joueur.']},
'making-is-a-form-of-thinking': {title: 'Fabriquer est une forme de pensée', paragraphs: ['MIT News décrit des travaux qui enseignent des compétences de fabrication informatique par le jeu, en reliant activités ludiques, création et bricolage. C’est un article d’actualité universitaire, pas une évaluation randomisée de tous les résultats d’apprentissage par le jeu. L’affirmation utile porte donc sur la posture : laisser les apprenants fabriquer, voir la réponse et partager le résultat.','Cette posture fait de l’explication une conséquence de l’activité. On comprend plus profondément un système lorsque l’explication répond à une question déjà ressentie dans ses mains.']},
'the-outbrick-question': {title: 'La question d’OutBrick', paragraphs: ['Les plateaux d’OutBrick sont assez petits pour poser une question précise : si cette brique bouge d’abord, quel couloir reste ouvert ? On peut essayer, annuler, comparer et finir par reconnaître la relation. Le jeu n’a pas besoin d’appeler cela une leçon pour faire pratiquer le raisonnement.','L’essentiel est la sincérité du retour. Un coup doit changer le plateau d’une façon examinable. Le mystère peut créer la curiosité au départ, mais la clarté lui permet de devenir compréhension.'], bullets: ['Montrer la question dans la disposition','Rendre les expériences réversibles','Donner un retour qui explique l’état','Récompenser un meilleur modèle, pas un hasard heureux']},
'leave-with-a-better-question': {title: 'Repartir avec une meilleure question', paragraphs: ['Un bon jeu d’apprentissage ne finit pas chaque séance par un score censé résumer le joueur. Il laisse une question plus précise pour le plateau suivant. C’est une mesure plus discrète de progression, mais souvent celle qui appartient au joueur.','La façon d’enseigner d’OutBrick est modeste : aider à remarquer une relation, faire un choix délibéré et sentir que son attention a changé les possibilités.']}
}, pullQuote: 'Le mystère peut créer la curiosité au départ, mais la clarté lui permet de devenir compréhension.', faqs: []
},
'animal-crossing-shared-time': {
title: 'Animal Crossing : l’architecture du temps partagé', dek: 'Pourquoi routines, rôles et jeu personnel donnent une présence sociale à un lieu numérique, même à distance.', imageAlt: 'Un chemin accueillant sur une île, avec table partagée, lanternes, plantes et petites maisons au crépuscule', tags: ['Animal Crossing','jeu social','routines','communauté'], intro: 'Le temps partagé ne ressemble pas toujours à une action simultanée. Parfois, c’est un lieu entretenu, une routine comparée ou une identité apportée à un univers qui attend votre retour.', keyTakeaways: ['Des recherches évaluées par les pairs sur Animal Crossing: New Horizons décrivent le remplacement de routines, la connexion sociale, l’autonomie et les identités.','Un jeu social peut créer du lien par la présence et l’interprétation partagée, pas seulement par la compétition directe.','OutBrick garde un cœur solitaire, mais conçoit ses plateaux et son journal comme des choses à commenter et transmettre.'], sections: {
'a-place-that-waits': {title: 'Un lieu qui attend', paragraphs: ['L’article de Comerford dans Persona Studies examine Animal Crossing: New Horizons à partir d’entretiens et d’une enquête auprès de près de 2 000 joueurs. Il décrit l’usage du jeu pour remplacer des routines, maintenir les liens sociaux, exercer son autonomie et construire des identités pendant une période d’isolement social. Le contexte historique est précis, mais l’observation de conception voyage : un lieu peut paraître social parce qu’il garde les traces des choix entre les visites.','Un monde qui attend crée un rythme différent d’un match qui n’existe que lorsque tout le monde est connecté. On peut apporter un petit geste, partir et revenir dans un univers continu.']},
'roles-make-room-for-people': {title: 'Les rôles font une place aux personnes', paragraphs: ['Le jeu personnel donne un rôle que les règles ne prescrivent pas entièrement. L’un devient jardinier, l’autre hôte, collectionneur ou aménageur d’un coin pour les visiteurs. Ces rôles ne sont pas nécessaires pour finir, ce qui leur permet de devenir significatifs plutôt que seulement fonctionnels.','C’est une forme d’autonomie. Le système offre des possibilités, mais le joueur décide quelle personne il veut être dans l’espace. Le lien peut alors grandir grâce aux histoires rendues possibles par ces choix.']},
'outbrick-as-a-shared-object': {title: 'OutBrick comme objet partagé', paragraphs: ['OutBrick n’est volontairement pas un fil social. Un puzzle peut pourtant devenir un objet partagé quand on explique son goulet, envoie un défi dans Messages ou demande à un ami comment il lit la même forme. Les défis Game Center vont à quelqu’un que vous connaissez vraiment. Le plateau est un petit lieu d’interprétation.','Le journal prolonge cet espace. Nous écrivons sur nos choix pour montrer la réflexion autour du jeu, pas seulement sa surface. Le but est de relier une pause solitaire à une pratique plus vaste de l’observation.']},
'design-for-returning-together': {title: 'Concevoir pour revenir ensemble', paragraphs: ['Les espaces partagés les plus bienveillants n’exigent pas les mêmes horaires. Ils laissent une trace que l’on peut reprendre plus tard et accueillent différents degrés de participation. On peut venir cinq minutes, décorer un coin ou simplement voir ce qui a changé.','C’est une norme utile pour l’écosystème d’OutBrick : chaque plateau doit se suffire, tandis que les histoires autour donnent davantage de façons de se sentir accompagné.']}
}, pullQuote: 'Un lieu peut paraître social parce qu’il garde les traces des choix entre les visites.', faqs: []
},
'papers-please-meaningful-friction': {
title: 'Papers, Please : une friction qui a du sens', dek: 'Comment une action répétée devient une question morale, et pourquoi la meilleure friction demande de décider, pas seulement d’attendre.', imageAlt: 'Un bureau austère avec des papiers tamponnés, une file d’attente et une lumière chaude évoquant des choix lourds de conséquences', tags: ['Papers, Please','friction significative','éthique dans les jeux','conception de systèmes'], intro: 'La friction n’est pas automatiquement de la profondeur. Parfois, ce n’est qu’un menu lent. Une friction significative rend une décision plus difficile parce que ses conséquences sont compréhensibles et comptent pour le joueur.', keyTakeaways: ['Papers, Please rend la procédure expressive en réunissant règles, temps, argent et enjeux humains dans le même espace de décision.','La tension éthique fonctionne mieux quand les valeurs concurrentes sont lisibles plutôt que la réponse cachée.','OutBrick utilise une version plus douce : le prochain coup peut être exigeant sans que l’interface soit hostile.'], sections: {
'procedure-becomes-a-question': {title: 'La procédure devient une question', paragraphs: ['Papers, Please commence par une action administrative répétée : examiner les documents, comparer les détails, décider. La description officielle place le joueur dans le rôle d’un inspecteur de l’immigration d’un État dystopique fictif. La procédure est simple à apprendre, mais le contexte change constamment son sens.','Une règle devient expressive quand le joueur comprend à la fois ce que le système demande et ce que coûte son choix. Inutile de faire un long discours avant chaque décision : la tension vit entre la liste de contrôle et la personne devant elle.']},
'friction-with-a-human-edge': {title: 'Une friction à dimension humaine', paragraphs: ['Une contrainte significative crée un conflit que l’on peut nommer. La précision peut protéger un emploi, la vitesse une famille, et la sévérité une personne tout en en blessant une autre. Le jeu n’offre aucune unique bonne réponse morale. Son système fait ressentir le choc entre les valeurs.','Les recherches sur l’autonomie et la compétence expliquent en partie cette force. Il faut assez de contrôle pour assumer son choix et assez de retours pour comprendre sa conséquence. Si le résultat est arbitraire, la tension devient frustration.']},
'what-outbrick-keeps': {title: 'Ce qu’OutBrick retient', paragraphs: ['OutBrick n’a ni poste-frontière ni dilemme moral. Sa friction significative est plus petite : choisir quelle relation préserver. Déplacer une brique peut fermer un couloir, retarder une correspondance ou révéler que le coup apparemment évident était un piège.','L’interface ne doit pas ajouter de douleur arbitraire. Le défi appartient à la relation spatiale, pas à un minuteur caché, une icône obscure ou une annulation rare : c’est pourquoi OutBrick n’a aucune horloge et offre une première annulation gratuite à chaque plateau. Voilà la limite entre une friction qui fait penser et celle qui consomme la patience. Elle traverse aussi [notre conception d’une difficulté plus bienveillante](/blog/kinder-difficulty-curve).'], bullets: ['Placer la difficulté dans l’idée, pas les commandes','Montrer assez de conséquences pour que les choix comptent','Permettre de se remettre d’une expérience','Garder le but lisible et le chemin ouvert']},
'let-the-player-name-the-cost': {title: 'Permettre de nommer le coût', paragraphs: ['Les systèmes les plus mémorables permettent de dire ce que l’on a échangé. « J’ai protégé ce couloir et perdu cette ouverture. » Cette phrase fait du puzzle une décision plutôt qu’une suite de boutons.','OutBrick veut un coût assez petit pour une courte séance, mais assez réel pour que la réussite soit méritée. Un peu de friction enrichit un jeu calme si le joueur garde le contrôle du sens.']}
}, pullQuote: 'La friction n’est pas automatiquement de la profondeur. Parfois, ce n’est qu’un menu lent.', faqs: []
},
'how-games-become-habits': {
title: 'Jeux et habitudes : signal, choix, conclusion', dek: 'Un regard pratique et attentif aux recherches sur les boucles qui font revenir les joueurs et les choix qui gardent ce retour volontaire.', imageAlt: 'Un chemin circulaire calme de petits moments de jeu, du contexte au choix puis à un arrêt clair', tags: ['habitudes de jeu','conception comportementale','pratique de jeu saine','autonomie du joueur'], intro: 'Une habitude n’est pas une addiction, et un retour n’est pas une compulsion. Comprendre la différence aide à créer des invitations faciles à accepter, et tout aussi faciles à refuser.', keyTakeaways: ['Les recherches sur les habitudes évoquent des signaux situationnels et des routines apprises, tandis que le jeu problématique implique une altération du fonctionnement et une perte de contrôle.','Les récompenses peuvent engager sans être automatiquement nuisibles ; contexte, différences individuelles et résultats comptent.','La boucle d’OutBrick est signal, choix, conclusion : une entrée claire, un coup significatif et une ligne d’arrivée qui respecte la prochaine décision.'], sections: {
'a-cue-is-not-a-command': {title: 'Un signal n’est pas un ordre', paragraphs: ['Un signal est le contexte qui rend une action disponible : un trajet calme, une tuile quotidienne, une icône familière ou l’instant après une tâche. Une étude indexée dans PubMed auprès de joueurs de MMORPG a examiné la sensibilité aux signaux situationnels avec le jeu excessif et problématique. Son résultat invite à ne pas considérer toute boucle répétable comme neutre, mais ne prouve pas que tous les jeux et joueurs développent le même schéma.','Les concepteurs doivent donc se demander ce que promet le signal. Un moment délimité de jeu, ou une chaîne d’obligations inachevées ? La réponse appartient autant au système environnant qu’à la récompense.']},
'the-choice-needs-to-belong-to-the-player': {title: 'Le choix doit appartenir au joueur', paragraphs: ['Une boucle ressentie comme saine donne une raison de choisir, pas seulement d’obéir. Des objectifs clairs et un retour immédiat peuvent soutenir la compétence ; des chemins facultatifs préservent l’autonomie. Le lien peut venir d’un rituel partagé, mais ne doit pas exiger de chacun une performance publique.','C’est pourquoi OutBrick garde le prochain plateau visible sans le rendre urgent. L’invitation est claire ; la décision reste vôtre.']},
'closure-matters': {title: 'La conclusion compte', paragraphs: ['La conclusion est ce que beaucoup de systèmes de fidélisation évitent volontairement. Un état final clair indique que la séance est terminée, la progression sauvegardée et le prochain retour peut commencer proprement. Sans cela, on peut continuer simplement parce que le système n’annonce jamais un bon point d’arrêt.','Les recherches sur les éléments récompensants et le jeu problématique examinent la relation entre divers types de récompenses et le comportement des adolescents. Il ne faut pas en déduire que les récompenses nuisent à tous. Elles soutiennent une question plus prudente : que fait cette récompense à la capacité de décider quand c’est assez ?']},
'outbricks-bounded-loop': {title: 'La boucle délimitée d’OutBrick', paragraphs: ['La boucle voulue d’OutBrick est volontairement simple. Un contexte familier fait ouvrir l’application, un plateau pose une question, on joue un coup et la carte de réussite offre une pause naturelle. Le Voyage génère des plateaux après le deux-millième pour qui en veut davantage, sans avaler le sens des chapitres précédents. Le bonus quotidien est de cent pièces pour la première réussite du jour, pas une série remise à zéro.','La mesure du succès n’est pas « le joueur est-il resté ? », mais « s’est-il senti libre de décider ? ». Un jeu mérite une autre séance lorsque la première s’achève avec la confiance intacte.'], bullets: ['Un signal qui explique ce qui est disponible','Un choix aux conséquences visibles','Une récompense qui ne cache pas la ligne d’arrivée','Un retour sans pénalité d’absence']}
}, pullQuote: 'Un jeu mérite une autre séance lorsque la première s’achève avec la confiance intacte.', faqs: [{question: 'Un jeu quotidien est-il automatiquement une mauvaise habitude ?', answer: 'Non. Un rituel quotidien peut être volontaire et agréable. L’essentiel est de garder le contrôle et de vérifier si le jeu empiète sur le sommeil, les responsabilités, les relations ou d’autres activités importantes.'},{question: 'Pourquoi OutBrick propose-t-il du jeu quotidien ?', answer: 'Un bonus quotidien de pièces donne un petit rythme facultatif. C’est une invitation avec une fin claire, pas une série qui transforme l’absence en échec.'}]
},
'commuter-puzzle-two-minute': {
title: 'Le puzzle des trajets : une place pour deux minutes', dek: 'Concevoir pour l’attention interrompue, les petits écrans et le bel intervalle entre « pas le temps » et « j’ai deux minutes ».', imageAlt: 'Un puzzle géométrique compact près d’une fenêtre calme pendant une courte pause de trajet', tags: ['courtes séances','jeux de trajet','conception mobile','jeux de puzzle'], intro: 'Le puzzle des trajets passe un autre contrat avec l’attention qu’un jeu sur console : clarifier vite l’état, respecter l’interruption et rendre deux minutes complètes plutôt qu’inachevées.', keyTakeaways: ['Concevoir des séances courtes tient autant à l’adéquation cognitive qu’au temps écoulé.','Les recherches pilotes sur les puzzles sur tablette éclairent la faisabilité et le bien-être sans prouver des bénéfices universels.','OutBrick considère l’interruption comme normale : état lisible, annulation gratuite sur chaque plateau et position exactement conservée au retour.'], sections: {
'design-for-the-interruption': {title: 'Concevoir pour l’interruption', paragraphs: ['Un jeu de trajet se joue autour des annonces, portes, messages et du simple besoin de relever les yeux. La première question n’est donc pas « comment maximiser l’immersion ? », mais « le joueur comprend-il où il en est lorsque son attention revient ? ».','Un état lisible est une forme de soin. Un plateau clair, des commandes stables et une pause visible réduisent la taxe de mémoire liée à l’interruption.']},
'two-minutes-can-still-have-a-shape': {title: 'Deux minutes peuvent avoir une forme', paragraphs: ['Une courte séance doit avoir un début, un milieu et une fin. Le début est la reconnaissance : que demande le puzzle ? Le milieu est un choix : quelle relation tester ? La fin est un résultat : qu’est-ce qui a changé et ai-je envie de continuer ?','Cette forme rend le jeu substantiel sans être long. On reçoit une unité d’attention complète plutôt qu’un fragment découpé dans une obligation plus grande.']},
'what-the-pilot-can-tell-us': {title: 'Ce qu’une étude pilote peut, ou non, nous dire', paragraphs: ['Urwyler et ses collègues ont étudié une intervention de puzzles sur tablette dans un essai pilote randomisé contrôlé de faisabilité auprès d’adultes en bonne santé. Une étude pilote aide à comprendre recrutement, adhésion, mesure et possibilité d’une étude plus vaste. Elle ne peut pas établir que tout court puzzle améliore cognition ou bien-être.','Cette distinction est utile aux équipes produit. On peut emprunter une question de recherche — l’expérience s’accorde-t-elle avec la journée et peut-on l’utiliser régulièrement ? — sans emprunter une conclusion que l’étude n’a pas tirée.']},
'outbrick-in-the-gap': {title: 'OutBrick dans l’intervalle', paragraphs: ['OutBrick est fait pour l’intervalle entre les obligations. Le plateau se lit vite, sa première annulation est gratuite et sa réussite n’exige pas une longue préparation. Si le train arrive ou le café est prêt, verrouiller le téléphone laisse le plateau exactement en place : l’interruption elle-même ne vous coûte jamais rien.','Ce n’est pas de la productivité déguisée en jeu, seulement un petit jeu qui comprend la forme d’une vraie journée et permet d’en apprécier les intervalles sans leur demander de grandir.'], bullets: ['Commencer par un plateau qui s’explique','Rendre l’interruption sûre','Offrir un point d’arrêt naturel','Laisser une séance courte rester un loisir']}
}, pullQuote: 'Un état lisible est une forme de soin.', faqs: [{question: 'Combien de temps dure un plateau OutBrick ?', answer: 'Environ deux minutes en général, mais cela dépend du plateau et du joueur. Il n’y a aucun minuteur. Le plateau limite les coups, pas les minutes : réfléchir aussi longtemps que vous voulez est gratuit.'},{question: 'Puis-je laisser un plateau inachevé ?', answer: 'Oui, et l’interruption est gratuite : verrouillez le téléphone ou changez d’application, le plateau attend tel quel. Revenir entièrement à la carte est le seul cas qui coûte : un plateau où vous avez déjà joué consomme une vie, après avertissement, et une vie revient seule toutes les trente minutes. Quitter un plateau terminé ne coûte jamais rien.'}]
},
'apple-watch-puzzle-games': {
title: 'Puzzles Apple Watch : jouer sur un petit écran', dek: 'Plateaux lisibles, grandes pièces, Digital Crown, haptique et autonomie : ce qui fait fonctionner un puzzle sur Apple Watch.', imageAlt: 'Un cadre de montre illustré autour d’un vrai plateau OutBrick sur un fond de briques indigo, avec Bloo et Poppy de chaque côté', tags: ['puzzles Apple Watch','jeux Apple Watch','watchOS','conception de jeux'], intro: 'La plupart des puzzles sont conçus pour un écran tenu en main que l’on regarde quelques minutes. L’écran Apple Watch est au poignet, reçoit un regard de quelques secondes et se manipule avec l’autre main. Cela change presque toutes les décisions, de la taille des pièces à la sensation d’une réussite. OutBrick dispose d’un jeu Apple Watch autonome : j’ai donc beaucoup réfléchi à ces questions. Cet article traite de la conception en général : les recommandations d’Apple et ce que je cherche dans un puzzle au poignet.', keyTakeaways: ['Sur montre, on joue par coups d’œil. Apple décrit des interactions souvent inférieures à une minute : le puzzle doit être lisible immédiatement et pouvoir être quitté en plein mouvement sans risque.','Un petit plateau avec de grandes pièces vaut mieux qu’une interface de téléphone réduite. Apple recommande des boutons watchOS de 44 × 44 points par défaut, jamais moins de 28 × 28.','L’haptique sert mieux de ponctuation : un sens clair par motif, utilisé avec parcimonie et renforçant ce que montre l’écran.'], sections: {
'design-for-the-glance': {title: 'Concevoir pour le coup d’œil', paragraphs: ['La description de l’usage d’une montre par Apple est le meilleur cahier des charges pour un puzzle au poignet. On lève le bras, tient l’écran à environ trente centimètres des yeux et utilise l’autre main. On regarde la montre de nombreuses fois par jour, parfois moins d’une minute. Les bonnes pratiques watchOS commencent par la même idée : des interactions rapides, lisibles d’un coup d’œil, sur un seul écran.','Pour un puzzle, cela élimine beaucoup de choses. Un plateau à faire défiler est exclu : tout l’état doit être visible le temps de lever le poignet. De même, trente petites pièces ne se lisent pas en un regard. Les plateaux adaptés sont petits, avec peu de pièces, un contraste fort et un but évident. La profondeur doit venir des obstacles mutuels, pas du nombre de pièces.','Le texte demande la même attention. Apple indique pour les jeux une taille par défaut de 16 points sur watchOS et un minimum de 12. Tout ce qu’il faut lire pendant un plateau, comme le compteur de coups, doit être à la taille par défaut ou au-dessus. Ce qui peut être omis de la version au poignet devrait probablement l’être.']},
'input-on-the-wrist': {title: 'Toucher, glisser et utiliser la Digital Crown', paragraphs: ['Sur montre, on utilise les gestes connus de l’iPhone : toucher, balayer et faire glisser. L’échelle change. Un doigt couvre une grande partie de l’écran, cachant à la fois la pièce et sa destination. Apple recommande des boutons de 44 × 44 points par défaut sur watchOS, jamais moins de 28 × 28. Les pièces suivent cette logique : plus petites qu’un doigt, elles seront manquées ou confondues avec la voisine.','La Digital Crown est l’autre entrée. Depuis watchOS 10, Apple la traite comme le principal moyen de navigation : sa rotation fait défiler les listes et passe entre les écrans paginés verticalement. Les applications reçoivent les rotations, pas les pressions réservées au système. Apple demande aussi une interaction tactile équivalente et une réponse visuelle à la rotation, sans quoi on pense qu’elle ne fait rien.','Pour les puzzles, la Crown convient aux choix sur un axe : parcourir les niveaux, sélectionner une pièce ou remonter les coups. Elle convient mal au déplacement sur une grille à deux dimensions. Tout ce qu’elle permet doit rester possible au doigt. Pas non plus de secours par manette : les recommandations d’Apple indiquent que watchOS est la seule plateforme Apple sans prise en charge des manettes physiques.']},
'sessions-in-seconds': {title: 'Des séances mesurées en secondes', paragraphs: ['Un puzzle sur téléphone peut supposer quelques minutes de disponibilité. Pas un puzzle sur montre. Le poignet descend quand le bus arrive, que la bouilloire bout ou que quelqu’un parle ; le jeu doit l’accepter sans pénalité. Il faut donc sauvegarder après chaque coup, retrouver exactement la position au prochain regard et ne rien laisser s’épuiser pendant que l’écran est éteint.','Les horloges en sont l’exemple le plus clair. Un compte à rebours sur montre punit précisément l’usage pour lequel elle est faite : regarder ailleurs. Une limite de coups fonctionne mieux : elle demande de ne pas gaspiller les mouvements, puis attend. OutBrick n’a aucune horloge et un plateau dure environ deux minutes, déjà court pour un puzzle. Le raisonnement est expliqué dans [pourquoi les puzzles de deux minutes font du bien](/blog/why-two-minute-puzzles-feel-good).','La progression compte aussi. Une séance au poignet représente un plateau, parfois deux. Longues chaînes d’objectifs, tâches quotidiennes exigeant dix plateaux et scènes entre niveaux vont à l’encontre de cet usage. Un seul plateau doit sembler complet, pour qu’abaisser le bras ressemble à une fin plutôt qu’à un abandon.']},
'haptics-as-punctuation': {title: 'L’haptique comme ponctuation', paragraphs: ['La montre touche la peau, ce qui rend l’haptique particulièrement efficace. watchOS définit des motifs intégrés, chacun avec son sens, joués par le Taptic Engine et associés à un son. Apple conseille de les utiliser selon leur signification documentée et de manière cohérente, pour que chaque motif soit clairement lié à l’action qui le provoque.','Peu d’événements de puzzle méritent d’être ressentis : une pièce à une place utile, un mouvement bloqué et une réussite. Donnez à chacun un motif stable. Si la même vibration signifie « bloqué » et « résolu », le joueur cesse de lui faire confiance. Apple met aussi en garde contre l’excès : un retour agréable de temps à autre devient fatigant quand il se répète. Sur montre, un tapotement à chaque glissement transforme vite un jeu calme en bourdonnement.','Le test d’Apple est bon : le meilleur retour haptique passe souvent inaperçu, mais manque lorsqu’on le désactive. Il doit soutenir l’écran, jamais le remplacer, car certains jouent avec l’haptique coupée.']},
'standalone-or-companion': {title: 'Autonome ou compagnon', paragraphs: ['Un jeu sur montre peut arriver de deux façons. La documentation d’Apple décrit des applications exclusivement watchOS sans application iPhone, et des applications avec compagnon iPhone installables et utilisables sans lui. Apple encourage l’indépendance dans les deux cas, car on attend de la montre qu’elle fonctionne sans téléphone. Avec un compagnon, les achats intégrés sont universels : un achat est disponible sur les deux appareils.','Pour le joueur, la question est plus simple : le jeu fonctionne-t-il seul ou sert-il de télécommande au téléphone ? Un jeu autonome se joue pendant une promenade en laissant le téléphone chez soi. OutBrick possède un jeu Apple Watch autonome, avec des versions iPhone, iPad, Mac, Apple TV et Apple Vision Pro. La progression reste dans votre iCloud : un nouvel appareil connecté au même compte reprend où l’ancien s’est arrêté.','Pour essayer les puzzles au poignet, voici ma courte liste. Beaucoup réussissent certains points et en manquent d’autres ; ceux qui satisfont les six restent généralement sur la montre.'], bullets: ['Tout le plateau est lisible en un regard, sans défilement.','Les pièces sont au moins aussi grandes que le bout du doigt.','Tout ce que fait la Digital Crown peut se faire au toucher.','Abaisser le poignet en cours de plateau ne coûte rien.','Chaque retour haptique a un seul sens et n’est pas constant.','Le jeu fonctionne sans téléphone à proximité.']}
}, pullQuote: 'Un compte à rebours sur montre punit précisément l’usage pour lequel elle est faite : regarder ailleurs.', faqs: [{question: 'Qu’est-ce qu’un bon puzzle Apple Watch ?', answer: 'Un plateau lisible en un regard, des pièces assez grandes pour le doigt, aucune horloge et une sauvegarde après chaque coup pour abaisser le poignet à tout moment. L’haptique aide si chaque motif a un seul sens et reste rare.'},{question: 'Les jeux Apple Watch ont-ils besoin d’un iPhone ?', answer: 'Pas toujours. Apple permet des applications exclusivement sur montre et des applications installables et utilisables indépendamment de leur compagnon iPhone. Le test le plus simple est de jouer avec le téléphone hors de portée.'},{question: 'OutBrick est-il sur Apple Watch ?', answer: 'Oui. OutBrick a un jeu Apple Watch autonome et fonctionne aussi sur iPhone, iPad, Mac, Apple TV et Apple Vision Pro.'},{question: 'Les jeux utilisent-ils la Digital Crown ?', answer: 'Oui. Les applications reçoivent les rotations pour faire défiler, sélectionner ou régler des valeurs. Les pressions sont réservées au système, et Apple demande un équivalent tactile à tout ce que fait la Crown.'}]
},
'apple-vision-pro-puzzle-games': {
title: 'Puzzles Apple Vision Pro : concevoir pour l’espace', dek: 'Confort, regard et pincement, fenêtres ou immersion, jeu assis et pièces lisibles : réussir un puzzle sur Apple Vision Pro.', imageAlt: 'Trois fenêtres arrondies flottantes montrant un vrai plateau OutBrick et deux villages en briques sur un ciel violet doux, avec Vio et Sprout dessous', tags: ['puzzles Vision Pro','jeux Apple Vision Pro','visionOS','conception de jeux'], intro: 'Un puzzle sur Apple Vision Pro part d’un lieu inhabituel. Le plateau n’a plus de bord défini par le verre : il flotte où le joueur le place, à la taille qui lui convient, et l’on choisit les objets du regard. Cette liberté améliore certaines habitudes de puzzle et en dégrade d’autres. OutBrick fonctionne sur Apple Vision Pro, mais cet article examine la conception en général à partir des Human Interface Guidelines d’Apple et de notre réflexion sur le confort au-delà de quelques minutes.', keyTakeaways: ['Le confort vient d’abord. Apple conseille un contenu devant le joueur, à bonne distance, utilisable avec les mains sur les genoux.','Le regard sert à viser : les pièces ont besoin d’espace et de formes arrondies où l’œil puisse se poser.','La plupart des puzzles ont leur place dans une fenêtre. L’immersion se justifie pour un moment, rarement pour tout le jeu.'], sections: {
'comfort-first': {title: 'Le confort avant le spectacle', paragraphs: ['L’introduction d’Apple à la plateforme commence à raison par l’ergonomie. Les utilisateurs voient le réel et le virtuel par les caméras, et Apple considère le confort visuel comme primordial. Ses conseils : afficher dans le champ de vision, éviter les placements exigeant de tourner la tête, les mouvements brusques ou trop rapides, et permettre des gestes avec les mains sur les genoux ou le long du corps.','Les puzzles s’y prêtent bien. Le plateau est un objet immobile qui vous attend. Rien n’a besoin de voler près de la tête ni de vous faire lever. Le risque est la tentation inverse : profiter de l’espace pour tout agrandir, rapprocher et surcharger. Un plateau occupant toute la vue force les yeux à voyager ; une célébration lançant des particules derrière les épaules est précisément le mouvement qu’Apple conseille d’éviter.','La distance compte autant que la taille. Apple recommande de placer à au moins un mètre le contenu lu ou utilisé longtemps, et de réserver la grande proximité aux interactions brèves. Un puzzle se regarde longtemps : il appartient donc à une distance de lecture plutôt qu’à portée de bras.']},
'gaze-and-pinch': {title: 'Regarder, c’est viser', paragraphs: ['Sur Vision Pro, on vise généralement un objet du regard et on le sélectionne par un geste indirect, comme joindre index et pouce, la main restant où elle est. Le système souligne l’objet regardé pour le confirmer avant le geste. Pour protéger la vie privée, visionOS ne communique pas le regard à l’application avant la sélection.','Cela influe directement sur le plateau. Les yeux bougent vite et légèrement même en fixant un point ; les cibles serrées sont donc difficiles à choisir. Apple suggère au moins 16 points d’espace autour des éléments interactifs ou des centres distants d’au moins 60 points. Il recommande aussi les formes arrondies : l’œil est attiré par les coins et peine à rester au centre d’une forme anguleuse. Une grille dense de carrés bord à bord est presque le pire cas. Des pièces arrondies, espacées et clairement soulignées conviennent mieux.','Le toucher direct reste possible : on peut tendre la main vers un objet virtuel. Apple précise que cela fatigue, surtout à hauteur des yeux ou au-dessus, et conseille de le réserver aux objets proches et aux durées courtes. Pour de nombreux plateaux, le geste indirect devrait être la norme, avec le toucher direct pour qui le préfère.']},
'window-or-immersive': {title: 'Une fenêtre d’abord, l’immersion au choix', paragraphs: ['Les applications visionOS commencent dans l’espace partagé, côte à côte dans des fenêtres déplaçables. Une application peut passer à un espace complet où elle est seule et choisir quelle part de la pièce remplacer. L’immersion mixte mêle son contenu au réel, la progressive en remplace une partie et la complète tout. Dans une expérience progressive, la Digital Crown règle la quantité visible.','Apple conseille de choisir le minimum d’immersion nécessaire à chaque moment et de commencer dans l’espace partagé ou en immersion mixte pour laisser le choix d’aller plus loin. Pour la plupart des puzzles, cela désigne une fenêtre. Un plateau est un objet délimité centré sur l’interface, ce à quoi les fenêtres sont destinées selon Apple ; elles gardent une boisson, une conversation ou une autre application en vue. Apple déconseille aussi trop de fenêtres, qui encombrent la pièce et compliquent le déplacement de l’application.','L’immersion peut tout de même mériter sa place. Un chapitre terminé ou une carte globale sont des moments où un bref passage dans un espace plus complet pourrait récompenser. Le test est de savoir si le joueur l’a choisi et peut en sortir facilement.']},
'seated-play': {title: 'Conçu pour rester assis', paragraphs: ['Vision Pro apporte le contenu aux personnes plutôt que de les y faire aller ; Apple recommande peu ou pas de mouvement physique, sauf nécessité. C’est facile pour un puzzle : faire glisser une pièce n’exige pas de marcher. Cela compte aussi pour la sécurité : Apple indique que l’appareil ne doit pas être utilisé pendant la conduite et précise que l’appareil n’est pas conçu pour se déplacer près de dangers comme escaliers, balcons ou rues.','Le jeu assis change aussi le rythme. Sur un canapé ou à un bureau, on peut jouer plus longtemps qu’au téléphone dans une file : les limites équitables comptent alors. Sans horloge et avec une limite de coups visible dès le départ, on peut réfléchir librement. OutBrick n’a aucun compte à rebours et chaque plateau affiche objectif et limite dès le premier toucher.','Apple indique aussi qu’un appui long sur la Digital Crown ramène le contenu devant soi à tout moment : inutile d’ajouter une commande dans l’application. Un puzzle qui reste où on l’a placé et revient sur demande fonctionne correctement.']},
'legible-pieces': {title: 'Des pièces lisibles', paragraphs: ['La lisibilité change lorsqu’un point n’est plus un nombre fixe de pixels. visionOS définit le point comme un angle et applique une échelle dynamique aux fenêtres : elles grandissent en s’éloignant et rétrécissent en se rapprochant, pour paraître de taille constante. Pour cette raison, Apple recommande les images vectorielles dans les jeux, afin qu’elles restent nettes lors du redimensionnement.','Apple indique pour les jeux visionOS un texte de 17 points par défaut, 12 minimum, et des boutons de 60 × 60 points par défaut, 28 × 28 minimum. La profondeur exige aussi de la retenue. Apple déconseille la profondeur du texte, plus difficile à lire lorsqu’il semble flotter au-dessus du fond, et rappelle que chaque changement de profondeur oblige les yeux à refaire la mise au point. Un plateau calme et clair avec un peu de relief sur les pièces se lit mieux qu’un empilement de couches flottantes.','La couleur garde ses obligations d’accessibilité. Apple Vision Pro prend en charge VoiceOver, Contrôle de sélection, Contrôle de temporisation et d’autres aides ; un puzzle de tri par couleur doit ajouter un second signal, comme une forme sur chaque pièce. Nous en parlons dans [couleur, forme et accessibilité](/blog/color-shape-accessibility). Avant de choisir un puzzle Vision Pro, vérifiez la liste ci-dessous.'], bullets: ['Jouable assis, mains sur les genoux.','Un plateau à bonne distance qui reste où vous le placez.','Des pièces espacées, arrondies et clairement soulignées au regard.','Une immersion proposée, jamais imposée.','Aucune horloge : réfléchir est gratuit.','La couleur n’est jamais le seul moyen de distinguer les pièces.']}
}, pullQuote: 'Le plateau est un objet immobile qui vous attend.', faqs: [{question: 'Existe-t-il des puzzles pour Apple Vision Pro ?', answer: 'Oui. OutBrick en est un : il fonctionne sur Apple Vision Pro, iPhone, iPad, Mac et Apple TV, et possède un jeu Apple Watch autonome.'},{question: 'Comment contrôler les jeux sur Apple Vision Pro ?', answer: 'Surtout avec les yeux et les mains. Regardez un objet pour le viser, puis joignez index et pouce pour le sélectionner. Le toucher direct des objets proches est possible ; Apple cite aussi manettes, claviers, souris, trackpads et manettes spatiales comme options.'},{question: 'Les jeux Vision Pro doivent-ils être immersifs ?', answer: 'Non. Les applications commencent dans l’espace partagé, en fenêtres avec d’autres applications, et Apple recommande seulement l’immersion nécessaire. Pour la plupart des puzzles, une fenêtre est le bon départ.'},{question: 'Dois-je me lever ou me déplacer ?', answer: 'Pas pour un puzzle bien conçu. Apple recommande peu ou pas de mouvement physique, avec des gestes possibles les mains sur les genoux.'}]
},
'games-like-tetris': {
title: 'Jeux comme Tetris : ce qui fait durer un puzzle', dek: 'Règles simples, plateau lisible, difficulté juste et boucle courte : pourquoi les puzzles de blocs durent et comment les juger.', imageAlt: 'Des briques à tenons rouges, jaunes, turquoise, violettes, bleues et vertes tombant vers un vrai plateau OutBrick sur fond indigo, observées par Bricko et Zippy', tags: ['jeux comme Tetris','puzzles de blocs','conception de puzzles','Tetris'], intro: 'Cherchez des jeux comme Tetris : vous trouverez des centaines de puzzles de blocs, qui tombent, glissent, se posent sur une grille ou se trient par couleur. La plupart sont oubliés une semaine après leur installation ; quelques-uns durent des années. Nous créons OutBrick, un puzzle de briques coulissantes : nous ne sommes donc pas neutres et ne classerons pas les jeux d’autrui. Nous pouvons décrire les qualités qui font durer un puzzle, avec Tetris comme référence, pour vous permettre de juger chaque jeu vous-même.', keyTakeaways: ['Les puzzles durables ont une règle apprise en quelques secondes et un état entier lisible d’un regard.','Une difficulté juste permet de relier chaque défaite à une décision, que la pression vienne de la vitesse, comme Tetris, ou d’une limite de coups.','Une boucle courte, d’une pièce à un plateau, permet au puzzle de trouver sa place dans les journées pendant des années.'], sections: {
'where-the-genre-starts': {title: 'L’origine du genre', paragraphs: ['The Tetris Company date la première version de 1984, quand Alexey Pajitnov la construisit sur Electronika 60 à Moscou. Elle traversa ensuite de longues négociations de droits jusqu’à la Game Boy de Nintendo, livrée avec Tetris. L’histoire vient du détenteur des droits : ses chiffres de vente sont ceux de l’entreprise, mais la trame est bien établie. Nous avons déjà étudié [comment les petites règles de Tetris restent ouvertes](/blog/tetris-simple-rules-infinite-variation).','Tetris a créé une famille plus qu’une formule : des pièces composées de cases carrées, une grille qui se remplit et une règle qui libère l’espace lorsqu’un motif est complet. Ses cousins font varier presque tout : chute par gravité, placement libre ou pièces fixes à glisser sur un plateau encombré jusqu’à une sortie. Les jeux qui durent partagent quelques qualités assez indépendantes de la variante choisie.']},
'simple-rules': {title: 'Une règle apprise en quelques secondes', paragraphs: ['Tetris s’explique en une phrase : assembler les pièces qui tombent pour remplir et effacer les lignes. Presque tous les puzzles durables ont une règle de cette taille ; leur profondeur vient des situations créées. Lorsqu’un chapitre de tutoriel précède le premier vrai niveau, les règles portent souvent un poids que le plateau devrait porter.','Les petites règles résistent aussi à la force brute, ce qui maintient leur intérêt. Breukelaar et ses collègues ont prouvé que même Tetris hors ligne, où toutes les pièces sont connues d’avance, est NP-complet pour des objectifs comme effacer le plus de lignes. Les puzzles coulissants sont formellement plus difficiles encore : Hearn et Demaine ont montré que le cas général est PSPACE-complet. Pour les joueurs, aucun raccourci connu ne résout donc tous les plateaux : chacun reste un problème neuf.','La règle d’OutBrick a la même taille : une brique glisse jusqu’à un obstacle ; faites-les toutes sortir par la porte de leur couleur. Clés et serrures, briques gelées, générateurs, convoyeurs et caisses arrivent sur la durée, mais chacun propose un nouvel angle de la même règle plutôt qu’une règle nouvelle.']},
'readable-state': {title: 'Un plateau lisible', paragraphs: ['À tout instant dans Tetris, tout l’état est visible : pile, trous, pièce actuelle et suivante. Rien d’important n’est caché. Cette lisibilité permet de planifier, et la planification fait ressentir le puzzle comme une réflexion plutôt que de la chance.','La recherche montre combien le regard porte la compétence. Kirsh et Maglio ont observé des joueurs tourner et déplacer les pièces pour voir plus vite leurs options, plutôt que les rapprocher de leur point de chute. Ils ont nommé cela des actions épistémiques : des mouvements facilitant la pensée plutôt que changeant la position. Lindstedt et Gray ont mesuré 39 caractéristiques chez 240 joueurs, chacun jouant une heure, et distingué les experts par un mélange intégré de perception, décision et action, appelé Mind’s Hand et Mind’s Eye.','La leçon pour les concepteurs est un état facile à saisir et des essais peu coûteux. Couleurs claires soutenues par la forme, pièces qui montrent leur fonctionnement et annulation invitant à expérimenter aident. Dans OutBrick, le mode daltonisme actif par défaut appose un glyphe sur chaque brique et porte, et la première annulation de chaque plateau est gratuite.']},
'fair-difficulty': {title: 'Une difficulté ressentie comme juste', paragraphs: ['Tetris se complique en accélérant. Cela fonctionne parce que les règles ne changent pas : on perd à cause de ses placements sous pression et on voit où la pile a dérapé. Une difficulté juste laisse voir pourquoi l’on perd. L’injustice est un plateau impossible, un rebondissement imprévisible ou une règle révélée après avoir coûté quelque chose.','La vitesse est une pression parmi d’autres. Un puzzle coulissant ou de placement peut demander de l’efficacité plutôt que des réflexes, avec une limite de coups à la place d’une horloge. Cela échange l’urgence du Tetris avancé contre du temps pour réfléchir, adapté à une autre humeur et souvent à un autre joueur. Les deux sont justes si la limite est visible avant de commencer.','L’équité exige aussi des plateaux possibles. Créé à la main ou généré, un puzzle doit être vérifié avant d’être montré. Les 2 000 plateaux d’OutBrick ont été résolus par un solveur avant publication, et chacun affiche objectif et limite de coups dès le premier toucher. La difficulté doit ensuite monter par étapes perceptibles, avec une idée nouvelle à la fois ; notre article sur [une difficulté plus bienveillante](/blog/kinder-difficulty-curve) explique comment.']},
'short-loop': {title: 'Une boucle qui entre dans la journée', paragraphs: ['La plus petite unité de Tetris est une pièce, quelques secondes de décision. La suivante est une partie, courte ou longue selon la compétence. Cet emboîtement explique en partie sa longévité. On peut jouer pendant que la bouilloire chauffe, et le même jeu peut captiver une heure.','Les puzzles durables gardent généralement une courte unité au centre. Un plateau ou une manche se finit en quelques minutes, possède une fin claire et ne coûte rien à quitter ensuite. Séries, objectifs quotidiens et événements peuvent l’entourer, mais lorsqu’ils dictent la durée, le jeu a échangé sa boucle contre un emploi du temps. Un plateau OutBrick dure environ deux minutes et le terminer ne coûte rien : c’est l’échelle qui convient le mieux au genre selon nous. Voir [pourquoi les puzzles de deux minutes font du bien](/blog/why-two-minute-puzzles-feel-good).','Quel que soit votre puzzle préféré, voici les questions des dix premières minutes. Si les puzzles coulissants vous sont nouveaux, [comment résoudre les puzzles de blocs coulissants](/blog/how-to-solve-sliding-block-puzzles) est un bon départ.'], bullets: ['Pouvez-vous expliquer la règle à un ami en une phrase ?','Voyez-vous en une fois tout ce qui compte sur le plateau ?','En cas de défaite, pouvez-vous identifier le coup responsable ?','Chaque niveau est-il connu comme résoluble, et les limites sont-elles annoncées ?','Pouvez-vous finir une manche en quelques minutes et arrêter sans rien perdre ?','Les nouvelles mécaniques arrivent-elles une par une, comme variantes de la même règle ?']}
}, pullQuote: 'Une difficulté juste laisse voir pourquoi l’on perd.', faqs: [{question: 'Quels types de jeux ressemblent à Tetris ?', answer: 'Tetris appartient à une vaste famille : blocs qui tombent, pièces à placer sur grille et blocs fixes à faire glisser sur un plateau encombré. OutBrick est un puzzle coulissant de tri par couleur. Au lieu de croire un classement, appliquez la liste de cet article aux jeux envisagés.'},{question: 'Quelle différence entre blocs tombants et coulissants ?', answer: 'Dans un jeu à blocs tombants, de nouvelles pièces arrivent et la vitesse crée généralement la pression. Dans un puzzle coulissant, elles sont généralement toutes présentes dès le départ et il faut trouver l’ordre de coups qui vide le plateau, souvent dans une limite de coups.'},{question: 'Pourquoi Tetris dure-t-il depuis si longtemps ?', answer: 'Une règle apprise en secondes, un état entièrement visible, une difficulté due à la vitesse plutôt qu’aux règles cachées et une manche assez courte pour quelques minutes libres. The Tetris Company date la première version de 1984.'},{question: 'OutBrick ressemble-t-il à Tetris ?', answer: 'Il partage les traits de famille : briques composées de cases carrées, petite règle et manches courtes. Ses briques glissent plutôt que tombent ; il n’a aucune horloge et chaque plateau a une limite de coups.'}]
},
'are-puzzle-games-good-for-your-brain': {
title: 'Les puzzles sont-ils bons pour le cerveau ?', dek: 'Les puzzles sont vendus comme entraînement cérébral. Études sur mémoire, âge et humeur : ce qu’elles montrent et ce qu’on ne peut honnêtement promettre.', imageAlt: 'Sprout et Peach de chaque côté d’un vrai plateau OutBrick en mode daltonisme sur iPhone, avec des briques à tenons sur un mur indigo', tags: ['puzzles et cerveau','entraînement cérébral','puzzles et mémoire','recherche sur les puzzles'], intro: 'Peu d’affirmations sont aussi répétées : les puzzles garderaient le cerveau jeune. Cela paraît juste et une industrie entière s’est construite dessus. La recherche est plus intéressante et modeste que le marketing. Nous créons OutBrick et avons toutes les raisons de souhaiter un oui retentissant. Ce n’est pas le cas, et nous préférons dire ce que les données soutiennent plutôt que vendre ce qu’elles ne soutiennent pas.', keyTakeaways: ['Pratiquer un puzzle améliore de façon fiable la performance à ce puzzle ; les preuves d’un transfert vers la pensée quotidienne sont faibles.','Les amateurs fréquents obtiennent souvent de meilleurs résultats aux tests, mais ces études ne montrent pas que les puzzles en sont la cause.','Les raisons les mieux étayées de jouer sont le plaisir, un bref mieux-être d’humeur et une agréable pause pour l’attention.'], sections: {
 'the-promise': {title: 'D’où vient la promesse', paragraphs: ['Dans les années 2000 et au début des années 2010, l’« entraînement cérébral » est devenu un marché. Applications et jeux portables promettaient mémoire plus vive, pensée plus rapide et protection contre le déclin, souvent avec un score quotidien. Le discours était simple : le cerveau est un muscle, les puzzles sa salle de sport.','En 2014, le Stanford Center on Longevity et le Max Planck Institute for Human Development ont publié une déclaration de scientifiques en réaction. Selon eux, les gains des jeux cérébraux sont généralement petits, étroits et brefs ; peu de preuves indiquent une amélioration des aptitudes quotidiennes ou une prévention de la maladie d’Alzheimer. La déclaration fut contestée et une lettre concurrente soutint que certains entraînements étaient étayés. Le débat lui-même indique que le oui n’est pas acquis.','Deux ans plus tard, la Federal Trade Commission américaine a conclu un accord avec Lumos Labs, créateur de Lumosity, au sujet de publicités prétendant améliorer les performances au travail et à l’école et retarder le déclin lié à l’âge. Le constat concernait des publicités insuffisamment étayées, pas un verdict scientifique d’inutilité. Une chose était claire : protéger le cerveau exige des preuves qui n’étaient pas là.']},
'near-and-far': {title: 'Mieux jouer ne signifie pas penser mieux partout', paragraphs: ['L’examen le plus complet est la revue de 2016 de Daniel Simons et collègues dans Psychological Science in the Public Interest. Ils ont analysé les études citées par les entreprises d’entraînement cérébral. Le schéma était cohérent : amélioration aux tâches pratiquées, moindre amélioration aux tâches proches et peu de preuves pour les tâches différentes ou la pensée quotidienne.','Les chercheurs distinguent transfert proche et lointain. Jouer beaucoup aux blocs coulissants rend meilleur aux blocs coulissants : on voit plus vite les obstacles et planifie plus loin. C’est un vrai apprentissage. Les preuves ne montrent pas qu’il se transfère au souvenir du lieu de stationnement ou au suivi d’une conversation complexe.','Aucune étude examinée ne satisfaisait toutes les normes de bon essai établies par les auteurs. Petits échantillons, groupes de comparaison faibles et possibilité que ceux qui attendent un progrès fassent simplement plus d’efforts au test rendent les résultats positifs moins fiables. Cela ne prouve pas que les puzzles sont mauvais. Cela invite à se méfier de ceux qui chiffrent le rajeunissement du cerveau promis.']},
'puzzlers-score-better': {title: 'Les amateurs réussissent mieux : la réserve', paragraphs: ['Les résultats souvent cités viennent de l’étude britannique PROTECT. En 2019, Helen Brooker et collègues ont décrit plus de 19 000 adultes de 50 à 93 ans, testés en ligne et interrogés sur la fréquence des puzzles de mots ou de nombres. Plus la fréquence déclarée augmentait, meilleurs étaient généralement les résultats sur toutes les mesures. Ceux qui ne faisaient jamais de puzzles obtenaient les plus faibles.','L’étude est vaste et soignée, mais reste un instantané. Elle montre une association, pas son sens causal. Les personnes à la pensée plus vive peuvent simplement aimer davantage les puzzles et en faire plus. Des experts indépendants l’ont souligné à la publication ; l’affirmation médiatique de cerveaux « huit ans plus jeunes » venait de la presse, pas des articles eux-mêmes.','Les essais assignant une activité permettent d’approcher la causalité, mais sont rares. En 2022, Devanand et collègues ont réparti aléatoirement 107 personnes avec trouble cognitif léger entre mots croisés en ligne et ensemble de jeux cérébraux informatiques pendant 78 semaines. Les mots croisés ont fait légèrement mieux sur la mesure cognitive principale. Sans groupe inactif, l’essai montre qu’ils surpassaient ces jeux, pas que l’un surpassait la vie ordinaire. Il rappelle aussi qu’un jeu cérébral informatisé n’est pas automatiquement meilleur.']},
'what-trials-show': {title: 'Les résultats des essais plus longs', paragraphs: ['L’essai durable le plus connu, ACTIVE, a recruté 2 832 adultes âgés aux États-Unis pour dix séances d’environ une heure de mémoire, raisonnement ou vitesse de traitement, avec quelques rappels ultérieurs. Dix ans après, les groupes raisonnement et vitesse étaient encore plus souvent au niveau initial ou au-dessus que le groupe témoin. L’avantage de mémoire s’était estompé. Les participants entraînés déclaraient aussi moins de difficultés quotidiennes, mais c’était autodéclaré.','Deux points comptent. ACTIVE entraînait des compétences précises avec des exercices spécialisés, pas des puzzles occasionnels : une application ne peut donc pas emprunter ses résultats. Même cet essai bien mené montre des effets modestes et précis. Promettre une protection large avec quelques minutes quotidiennes dépasse largement les meilleures données.','Les petites études d’applications ordinaires sont encore plus mitigées. Un essai pilote d’Urwyler et collègues a fait jouer onze adultes en bonne santé vingt minutes par jour sur tablette : amélioration d’une mesure d’attention, sans changement de cognition globale, d’humeur ou de qualité de vie. C’est une étude de faisabilité, pas une preuve dans un sens ou l’autre.']},
'honest-reasons': {title: 'Les raisons honnêtes de jouer', paragraphs: ['Si les puzzles ne sont pas une vitamine cérébrale prouvée, pourquoi jouer ? Parce que les raisons solides sont bonnes. Un problème délimité, un petit défi juste et la satisfaction de résoudre. De courtes séances occasionnelles ont été associées à une meilleure humeur après une tâche exigeante, comme expliqué dans [pourquoi deux minutes de puzzle peuvent permettre de souffler](/blog/why-two-minute-puzzles-feel-good). C’est une affirmation modeste, suffisante.','La déclaration scientifique de 2014 se terminait par un conseil utile : rester physiquement actif, mentalement engagé et socialement connecté. Le puzzle peut contribuer modestement au deuxième point, surtout partagé. Il ne remplace pas les deux autres, et aucun jeu ne devrait prétendre le contraire.','OutBrick a été conçu ainsi. Il ne fait aucune promesse de santé. Ses plateaux sont courts, résolubles et sans horloge pour réfléchir plutôt que courir. S’il devient un petit plaisir quotidien, c’est tout le but. Progresser est aussi un vrai apprentissage : notre guide [comment résoudre les puzzles coulissants](/blog/how-to-solve-sliding-block-puzzles) peut aider.'], bullets: ['Méfiez-vous des jeux promettant plus d’intelligence ou la prévention du déclin.','Choisissez les puzzles par plaisir : il entretient l’habitude.','Variez : des problèmes nouveaux stimulent plus que la répétition de ceux déjà maîtrisés.','Gardez les puzzles à côté du mouvement, du sommeil et des autres, pas à leur place.']}
}, pullQuote: 'On s’améliorait aux tâches pratiquées. Les preuves d’un transfert plus large restent minces.', faqs: [{question: 'Les puzzles améliorent-ils la mémoire ?', answer: 'Ils améliorent de façon fiable la compétence aux puzzles pratiqués. Les revues de recherche trouvent peu de preuves d’un transfert à la mémoire ou à la pensée quotidiennes.'},{question: 'Peuvent-ils prévenir la démence ?', answer: 'Aucune étude n’a montré cette prévention. Les amateurs fréquents réussissent souvent mieux aux tests, sans preuve que les puzzles en soient la cause. Des régulateurs ont sanctionné les entreprises prétendant autrement.'},{question: 'Les mots croisés sont-ils meilleurs que les applications cérébrales ?', answer: 'Dans un essai de 78 semaines avec trouble cognitif léger, les mots croisés en ligne ont légèrement surpassé des jeux informatiques sur la mesure principale. Sans groupe sans entraînement, il ne montre pas que l’un surpasse l’absence des deux.'},{question: 'OutBrick est-il un entraînement cérébral ?', answer: 'Non. C’est un puzzle coulissant de tri par couleur conçu pour le plaisir, sans promesse de santé. Ses plateaux sont courts, résolubles et sans horloge.'}]
},
'puzzle-games-for-older-adults': {
title: 'Puzzles pour les adultes âgés : bien choisir', dek: 'Texte lisible, grands boutons, aucune horloge et couleurs distinctes : choisir un puzzle à 50, 70 ou 90 ans.', imageAlt: 'Peach et Bloo de chaque côté d’un vrai plateau OutBrick sur iPad, avec de grandes briques à tenons sur un mur bleu', tags: ['puzzles pour adultes âgés','jeux pour seniors','puzzles accessibles','puzzles iPad'], intro: 'Beaucoup de joueurs de puzzles sur téléphone et tablette sont grands-parents, et nombre de jeux ne semblent pas pensés pour eux : boutons minuscules, texte pâle, compte à rebours et couleurs confondues. Voici un guide pratique pour choisir un puzzle à tout âge, pour soi ou pour préparer la tablette d’un parent. Nous créons OutBrick et l’utilisons comme exemple, mais chaque point s’applique à n’importe quel jeu.', keyTakeaways: ['Les adultes âgés représentent une grande part du public des puzzles mobiles et jouent surtout sur téléphone ou tablette.','Vérifiez avant tout la taille du texte et des boutons, le contraste des couleurs et l’absence d’horloge.','Activez d’abord les réglages d’accessibilité iPhone et iPad, puis voyez quels jeux les respectent.'], sections: {
'who-plays': {title: 'Les joueurs âgés font largement partie du public', paragraphs: ['L’étude AARP de 2023 indiquait que 45 % des Américains de 50 ans et plus jouent aux jeux vidéo, soit environ 52 millions de personnes, et que 84 % jouent sur smartphone. Puzzles et jeux de logique étaient les plus populaires, pratiqués par 73 % de ces joueurs, devant cartes, tuiles et jeux de mots. Près de la moitié jouent chaque jour.','Une étude AARP complémentaire en 2024 les a interrogés sur l’accessibilité. Environ deux tiers disent que les changements liés à l’âge, surtout visuels, influencent leur jeu, et la moitié ont rencontré au moins un problème d’accessibilité. Les demandes principales étaient texte réglable, désactivation des effets distrayants, prise en main facile et difficulté ajustable. Les chiffres sont américains, mais les problèmes universels.']},
'readable': {title: 'Un texte lisible et des boutons faciles à toucher', paragraphs: ['Petits textes et cibles tactiles étaient les principaux obstacles dans les tests d’utilisabilité prolongés de Nielsen Norman Group avec les plus de 65 ans ; ils faisaient davantage d’erreurs que les plus jeunes aux mêmes tâches. Les jeux ne diffèrent pas. Un niveau facile à résoudre mais difficile à voir, ou un bouton manqué souvent, transforme un puzzle reposant en corvée.','Les recommandations d’Apple prévoient 44 × 44 points par défaut pour les commandes iPhone et iPad et demandent un fort agrandissement du texte, idéalement par Dynamic Type. Les règles d’accessibilité web fixent un minimum inférieur de 24 × 24 pixels, 44 × 44 au niveau le plus strict. Inutile de mesurer : si vous touchez deux fois ou plissez les yeux, le jeu est trop petit pour vous.','Le test le plus rapide est de modifier le texte système. Sur iPhone ou iPad : Réglages, Accessibilité, Affichage et taille du texte, puis Police plus grande. Ouvrez ensuite le jeu. Les bons jeux s’agrandissent ; d’autres ignorent le réglage. Dans OutBrick, l’agrandissement s’applique partout, et sur iPad les briques sont assez grandes pour être touchées confortablement.']},
'colour': {title: 'Des couleurs faciles à distinguer', paragraphs: ['La vision des couleurs change avec l’âge, souvent autrement qu’on ne le pense. Le cristallin jaunit et les couleurs difficiles à séparer sont généralement bleus, violets et certains jaunes et verts, plutôt que le rouge et vert du daltonisme courant. Tamura et Sato ont trouvé que les adultes âgés mettaient beaucoup plus longtemps à repérer une cible différant de son environnement uniquement sur l’axe bleu-jaune.','Cela compte pour les jeux de tri et match-3, souvent fondés sur ces teintes. Cherchez un deuxième signal : symbole, forme ou motif sur chaque pièce. Le réglage Différencier sans couleur d’Apple, sous Affichage et taille du texte, le demande aux applications ; les bons jeux le respectent. OutBrick va plus loin : son mode daltonisme actif par défaut appose un glyphe distinct sur chaque brique et sa porte. Voir [pourquoi la couleur ne doit jamais être le seul indice](/blog/color-shape-accessibility).']},
'no-rush': {title: 'Sans horloge, précipitation ni surprise', paragraphs: ['Un compte à rebours est l’une des fonctions les moins accueillantes pour un joueur âgé. Les réactions ralentissent avec l’âge et le minuteur transforme la réflexion en test de réflexes. Cherchez des niveaux normaux sans horloge ou avec une limite de coups, pour réfléchir gratuitement. OutBrick n’a aucune horloge ; chaque plateau affiche sa limite avant le premier mouvement.','Vérifiez aussi les animations. Récompenses clignotantes, secousses et transitions plongeantes fatiguent beaucoup et gênent certains. Sur iPhone ou iPad : Réglages, Accessibilité, Animation, Réduire les animations remplace glissements et zooms par des fondus doux dans les applications compatibles. OutBrick le respecte partout.','Enfin, examinez le financement, source habituelle de surprises indésirables. Publicités automatiques, offres après l’échec et invitations à acheter désorientent les nouveaux joueurs et se touchent accidentellement. Le coût doit être clair. L’accueil d’OutBrick détaille [les coûts des vies, annulations et publicités](/#fair) : les publicités sont des vidéos récompensées qui ne commencent qu’après appui sur un bouton.']},
'checklist': {title: 'Une liste pour les dix premières minutes', paragraphs: ['Vous préparez le jeu pour quelqu’un ? Faites-le ensemble et laissez cette personne choisir l’apparence et les sensations. Activez d’abord l’accessibilité, connectez son compte Apple pour sauvegarder la progression et jouez côte à côte. Les jeux appréciés ensemble deviennent plus facilement une habitude partagée, bonne raison en soi. Soyons honnêtes : les puzzles sont un plaisir, pas un médicament. Nous avons examiné séparément [les recherches sur puzzles et cerveau](/blog/are-puzzle-games-good-for-your-brain).'], bullets: ['Le texte grandit-il avec Police plus grande ?','Touchez-vous chaque bouton du premier coup, même dans les coins ?','Chaque pièce se reconnaît-elle par forme ou symbole, pas seulement couleur ?','Les niveaux normaux sont-ils sans horloge ?','Réduire les animations est-il respecté ?','Quelque chose démarre-t-il, apparaît-il ou réclame-t-il de l’argent sans appui ?','Pouvez-vous arrêter à tout moment sans rien perdre ?','Le jeu fonctionne-t-il hors ligne, sans gêne liée au signal ?']}
}, pullQuote: 'Un niveau facile à résoudre mais difficile à voir transforme un puzzle reposant en corvée.', faqs: [{question: 'Qu’est-ce qu’un bon puzzle pour adultes âgés ?', answer: 'Texte lisible suivant la taille système, grands boutons, pièces distinguées par forme et couleur, aucun compte à rebours, mouvement calme et aucune publicité ou offre automatique.'},{question: 'iPad ou iPhone pour les puzzles ?', answer: 'L’iPad offre des pièces et boutons plus grands, souvent plus faciles à voir et toucher. Le téléphone se transporte mieux. De nombreux jeux, dont OutBrick, fonctionnent sur les deux avec une progression synchronisée par iCloud.'},{question: 'Quels réglages iPhone aident à jouer ?', answer: 'Dans Réglages, Accessibilité : Affichage et taille du texte pour Police plus grande, Texte en gras et Différencier sans couleur, et Animation pour Réduire les animations. Les jeux compatibles deviennent plus lisibles et calmes.'},{question: 'OutBrick convient-il aux joueurs âgés ?', answer: 'Il a été conçu pour cela : aucune horloge, mode daltonisme par défaut avec glyphe sur chaque brique, texte agrandi partout, Réduire les animations respecté et versions iPhone et iPad.'}]
},
'history-of-sliding-block-puzzles': {
title: 'Puzzles coulissants : du taquin à Rush Hour', dek: 'Un bureau de poste new-yorkais, la folie de 1880, la fausse revendication d’un célèbre auteur de puzzles et un puzzle de parking venu de Tokyo : comment les blocs coulissants sont devenus un classique.', imageAlt: 'Un plateau classique de taquin avec le 14 et le 15 inversés, près d’un vrai plateau OutBrick sur iPhone, avec Bloo et Sprout', tags: ['histoire des puzzles coulissants','taquin','Klotski','puzzle Rush Hour'], intro: 'Chaque fois que vous faites sortir une brique d’un plateau encombré d’OutBrick, vous jouez à un très vieux jeu. Les puzzles coulissants existent depuis près de 150 ans : leur histoire comprend un engouement national, une preuve mathématique publiée à son début, une des fausses revendications les plus durables de l’histoire des puzzles et un puzzle de parking de Tokyo devenu classique scolaire. Voici la version courte, avec les dates connues et les incertitudes clairement signalées.', keyTakeaways: ['Le taquin vient de Canastota, dans l’État de New York, et a gagné les États-Unis en 1880 ; Sam Loyd ne l’a pas inventé.','Presque dès son apparition, les mathématiciens ont prouvé que la moitié des positions initiales sont impossibles à résoudre.','Klotski et Rush Hour ont déplacé le défi du rangement des tuiles à la sortie d’un bloc, idée sur laquelle repose OutBrick.'], sections: {
'before-the-craze': {title: 'Avant l’engouement', paragraphs: ['L’idée centrale est un cadre contenant des pièces et juste trop peu de place : on déplace seulement une pièce dans l’espace vide. Elle était déjà sur papier avant la version célèbre. Un brevet américain accordé à Ernest Kinsey en 1878 décrit des blocs glissant dans un cadre avec un seul vide.','Le jeu qui a rendu l’idée célèbre est le taquin : quinze tuiles numérotées dans un plateau quatre par quatre, avec un vide. Les longues recherches de Jerry Slocum et Dic Sonneveld, présentées dans leur livre The 15 Puzzle de 2006, remontent à Noyes Chapman, maître de poste à Canastota, dans l’État de New York. Des versions étaient vendues sous le nom Gem Puzzle fin 1879.']},
'fifteen-craze': {title: '1880 : l’année du taquin', paragraphs: ['Dans les premiers mois de 1880, le taquin devint une folie. Il traversa les États-Unis en quelques semaines puis l’Europe, dans les bureaux, salons et journaux. Les récits divergent sur les semaines exactes, mais au printemps il était partout, puis déclinait en été. Chapman demanda un brevet qui fut refusé ; la raison est incertaine ; une explication plausible est que des brevets antérieurs couvraient déjà l’idée.','Certaines positions semblaient impossibles, et l’étaient réellement. En 1879, William Woolsey Johnson et William Story publièrent des notes dans l’American Journal of Mathematics montrant qu’exactement la moitié des dispositions ne peuvent être résolues. L’argument repose sur la parité : chaque glissement garde fixe un décompte pair ou impair caché ; une position au mauvais décompte reste inaccessible, quelle que soit la durée des essais.','Cela explique le tour le plus célèbre : échangez seulement le 14 et le 15 d’un plateau terminé. La position semble à un coup du but, mais est inaccessible.']},
'sam-loyd': {title: 'La revendication qui a trompé tout le monde', paragraphs: ['Pendant une grande partie du XXe siècle, le taquin fut attribué à Sam Loyd, l’auteur de puzzles le plus connu aux États-Unis. Il disait l’avoir inventé et offert un grand prix pour l’échange impossible 14–15. Slocum et Sonneveld ont trouvé que sa première revendication datait de 1891, plus de dix ans après l’engouement, et dura jusqu’à sa mort en 1911. Rien ne prouve son rôle dans l’invention ni l’existence du prix en 1880.','La revendication a persisté grâce à sa célébrité, aux réimpressions de ses livres et aux reprises ultérieures. Cela rappelle que l’histoire des puzzles, comme toute histoire, mérite vérification dans les archives.']},
'get-one-block-out': {title: 'Du rangement des tuiles à la sortie d’un bloc', paragraphs: ['La grande famille suivante changea le but. Au lieu d’ordonner les tuiles, il fallait amener un grand bloc vers une sortie parmi de plus petits. Un brevet déposé par Lewis W. Hardy en 1907 et accordé en 1912 décrit dix blocs de tailles différentes dans une boîte, déplaçables seulement par glissement. Un modèle très proche fut vendu comme Pennant Puzzle.','Des jeux semblables suivirent sous divers noms. Le Smithsonian conserve un Dad’s Puzzler, protégé en 1926, avec un grand carré, plusieurs rectangles et deux petits carrés. Cette famille est souvent appelée Klotski ; en Chine, Huarong Dao raconte un général échappant à une embuscade. Les solutions minimales des dispositions classiques atteignent environ 80 coups, selon le mode de comptage.','Dans les années 1990 apparut sa forme moderne la plus réussie. Le Japonais Nob Yoshigahara créa Tokyo Parking, un puzzle de voitures coulissantes ; Binary Arts, devenu ThinkFun, le publia aux États-Unis en 1996 sous le nom Rush Hour. Voitures et camions encombrent une petite grille ; on les glisse jusqu’à pouvoir sortir sa voiture. Des cartes de difficulté graduée en firent une série, devenue habituelle en classe et en famille.']},
'hard-for-computers': {title: 'Difficiles, même pour les ordinateurs', paragraphs: ['Ils ressemblent à des jouets, mais sont des objets sérieux en informatique. Il fallut attendre 1999 pour établir que toute position résoluble du taquin se termine en au plus 80 mouvements d’une tuile. Korf et Schultze l’ont confirmé par une recherche de 28 jours trouvant exactement dix-sept positions exigeant les 80.','En 2002, Gary Flake et Eric Baum ont prouvé que Rush Hour généralisé à toute taille de plateau est PSPACE-complet, classe réputée plus difficile que les célèbres problèmes NP-complets. Robert Hearn et Erik Demaine ont ensuite montré en 2005 que les puzzles coulissants généraux le sont aussi, même avec uniquement de petits dominos identiques. Aucun raccourci connu ne résout rapidement tous les plateaux : voilà pourquoi un bon puzzle reste intéressant.']},
'where-outbrick-fits': {title: 'La place d’OutBrick', paragraphs: ['OutBrick appartient à la branche de sortie des blocs, avec sa propre variation : chaque brique a une destination. Elle glisse jusqu’à un obstacle et ne sort que par la porte de sa couleur. Vider le plateau exige de trouver l’ordre, comme pour Hardy et Yoshigahara.','Les outils modernes auraient fait envie aux joueurs de 1880. Chacun des 2 000 plateaux d’OutBrick a été résolu par un solveur avant publication : personne ne rencontre un échange 14–15. Pour la pratique, notre guide [comment résoudre les puzzles coulissants](/blog/how-to-solve-sliding-block-puzzles) explique les stratégies, et vous pouvez [essayer un plateau dans le navigateur](/play).'], bullets: ['Fin des années 1870 : des blocs coulissants encadrés apparaissent dans les brevets américains.','Fin 1879 : le taquin est vendu ; Johnson et Story prouvent la moitié des positions impossibles.','1880 : l’engouement traverse les États-Unis et l’Europe.','1891 : Sam Loyd revendique pour la première fois l’invention.','1907–1912 : le puzzle de sortie de Hardy est breveté.','1996 : Rush Hour sort aux États-Unis.','2002–2005 : Rush Hour et les puzzles coulissants sont prouvés PSPACE-complets.']}
}, pullQuote: 'Échangez seulement le 14 et le 15 : la position semble à un coup du but, mais reste inaccessible.', faqs: [{question: 'Qui a inventé le taquin ?', answer: 'Les recherches de Jerry Slocum et Dic Sonneveld l’attribuent à Noyes Chapman, maître de poste de Canastota, New York. Vendu fin 1879, il devient une folie en 1880. Sam Loyd le revendique dès 1891, sans preuve d’invention.'},{question: 'Tout taquin est-il résoluble ?', answer: 'Non. Johnson et Story ont montré en 1879 qu’exactement la moitié des dispositions sont impossibles, chaque glissement préservant une parité cachée. Toute position résoluble se termine en au plus 80 mouvements d’une tuile.'},{question: 'Qu’est-ce que Klotski ?', answer: 'C’est un nom courant des puzzles où un grand bloc doit sortir parmi de plus petits. Une première version a été brevetée par Lewis W. Hardy, déposée en 1907 et accordée en 1912.'},{question: 'Qui a inventé Rush Hour ?', answer: 'Le concepteur japonais Nob Yoshigahara ; Binary Arts, renommé ThinkFun, l’a publié aux États-Unis en 1996.'}]
},
'verifying-2000-sliding-block-boards': {
title: 'Comment nous avons vérifié 2 000 plateaux', dek: 'Trouver un chemin n’est qu’un début. Voici comment nous avons rejoué une réussite par plateau avec les règles mêmes d’OutBrick.', imageAlt: 'Un vrai plateau coulissant OutBrick avec repères de couleur et glyphes, à côté des blocs du jeu', tags: ['développement de jeux','conception de puzzles','recherche de chemin','assurance qualité','puzzles coulissants'], intro: '« Deux mille plateaux, tous résolubles » semble une affirmation. C’est en réalité une chaîne : une recherche trouve un chemin ; celui-ci fonctionne encore depuis l’état initial réel ; chaque mouvement respecte les règles des joueurs. Pour OutBrick, recherche et vérification sont séparées, puis nous avons rejoué un témoin pour chaque plateau avant publication.', keyTakeaways: ['La recherche utilise A* pondéré et une heuristique ExitTable pour trouver vite un bon chemin, pas prouver qu’il est le plus court.','Un rejeu indépendant applique chaque mouvement sauvegardé selon les règles et rejette les résultats illégaux, non déterministes, hors limites, superposés ou non terminés.','Un budget de nœuds épuisé signifie « inconnu ». Cela ne prouve jamais l’absence de solution.'], sections: {
'one-rules-engine': {title: 'Commencer par un seul moteur de règles', paragraphs: ['Un solveur n’est fiable que si sa notion du mouvement correspond au jeu. Une pièce peut glisser jusqu’au mur, à une autre pièce ou à une porte refusant sa couleur. OutBrick ajoute des états : les clés modifient les portes, la glace demande plusieurs glissements et les générateurs introduisent des pièces en attente. Réimplémenter des règles simplifiées pour vérifier laisserait un vide exactement où une erreur pourrait se cacher.','La recherche demande donc au moteur du jeu les mouvements légaux et utilise le même code de transition que le jeu. La clé d’état comprend celui des portes et un compteur de coups replié lorsque des portes cycliques ou temporisées le rendent pertinent. Deux plateaux visuellement identiques mais aux portes dans des états actifs différents doivent rester des états de recherche distincts.']},
'search-finds-route': {title: 'Chercher un chemin, sans prétendre à la perfection', paragraphs: ['Le solveur utilise A* pondéré. Son heuristique ExitTable demande combien de glissements chaque pièce nécessiterait pour une sortie adaptée si les autres briques étaient retirées. Ce plateau relâché est moins coûteux à raisonner et estime utilement le travail restant. Renforcer le poids de l’heuristique favorise une réussite rapide.','Ce choix a une limite : le chemin utile n’est pas garanti le plus court. La recherche peut aussi atteindre son budget de nœuds. Le résultat est alors inconnu, pas impossible. Seul l’épuisement complet de l’espace d’états atteignables peut justifier l’absence de réussite. Distinguer ces issues empêche un délai ou une annulation de devenir une fausse affirmation sur le puzzle.']},
'replay-the-witness': {title: 'Rejouer le témoin depuis le plateau original', paragraphs: ['Trouver un chemin n’est pas la vérification finale. Pour chaque plateau créé, nous conservons un témoin : la suite de coups de l’état initial à la réussite. Le rejeu commence dans un état neuf, vérifie sa validité et applique les coups un par un selon les vraies règles. Un mouvement illégal fait immédiatement échouer le rejeu.','Le vérificateur rejoue aussi chaque coup depuis le même état précédent et compare état résultant, événements et résultat. Cela détecte les transitions différentes lors d’une répétition. Après chaque coup, il vérifie que chaque pièce reste sur une case valide et qu’aucune paire ne partage une case. À la fin, le plateau doit réellement être vide. Un chemin plausible ou laissant une brique ne compte pas.']},
'solvable-isnt-difficulty': {title: 'Résoluble ne signifie pas bien rythmé', paragraphs: ['Un témoin légal prouve l’existence d’un chemin. Il ne prouve pas qu’une personne le trouvera, le jugera juste ou ressentira la bonne difficulté. Le chemin du solveur n’établit pas non plus un nombre optimal de coups. Ce sont des questions séparées : le rejeu du pack entier sert de contrôle de correction, le rythme et la difficulté sont évalués à part.','La limite de coups doit aussi laisser la place au chemin vérifié. On peut réfléchir aussi longtemps que nécessaire : la limite compte les mouvements et OutBrick n’a aucune horloge. Le puzzle garde ainsi sa pression sans transformer la validation en minuteur.']},
'repeatable-release-check': {title: 'Un contrôle répétable avant publication', paragraphs: ['Le résultat utile n’est pas « le solveur a tourné une fois ». C’est que chaque plateau avait un témoin rejoué correctement selon les règles publiées. Si une règle ou un plateau change, le pack peut être revérifié ; le premier coup en échec indique ce qui a cassé : légalité, déterminisme, géométrie ou réussite finale.','C’est ainsi que nous avons contrôlé les 2 000 plateaux d’OutBrick avant publication. Essayez ce type de puzzle sur le [plateau gratuit du navigateur](/play), ou [téléchargez OutBrick pour iPhone et iPad](https://apps.apple.com/us/app/outbrick/id6807997465).']}
}, pullQuote: 'Un chemin trouvé est un candidat. Un rejeu correct selon les règles du jeu est une preuve.', faqs: [{question: 'Le solveur trouve-t-il la solution la plus courte ?', answer: 'Non. A* pondéré trouve rapidement un bon chemin de réussite, sans garantie d’optimalité. Le rejeu vérifie sa légalité et la réussite du plateau.'},{question: 'Que se passe-t-il au budget de nœuds ?', answer: 'Le résultat est inconnu, pas insoluble. Une limite de budget ou une annulation ne prouve pas l’absence de chemin.'},{question: 'Que signifie « vérifié par un solveur » ?', answer: 'Un chemin a été trouvé et rejoué depuis l’état initial selon les règles du jeu. Le rejeu vérifie mouvements légaux, transitions répétables, positions valides sans superposition et réussite complète.'}]
}
};
